};

import { GoogleGenAI } from "@google/genai";
import { League, RiskLevel, ParlayRecommendation } from "../types";

export const generateParlays = async (
  league: League,
  risk: RiskLevel,
  filters: string
): Promise<ParlayRecommendation[]> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API Key not found in environment variables.");
    }

    const ai = new GoogleGenAI({ apiKey });

    // Using gemini-2.5-pro for its ability to use Google Search tools (Grounding)
    const modelId = "gemini-2.5-pro";

    const isPlayerSearch = filters && filters.length > 2;

    const searchInstruction = isPlayerSearch
        ? `SEARCH STRATEGY (PLAYER FOCUS):
           1. Search for "${filters} player props today DraftKings FanDuel PrizePicks".
           2. Search for "${filters} stats last 5 games".
           3. Look specifically for discrepancies between DraftKings, FanDuel, and PrizePicks for this player.
           4. Find the live lines for Points, Rebounds, Assists, and Threes.`
        : `SEARCH STRATEGY (GENERAL PARLAY):
           1. Search for "${league} odds today draftkings" and "player props ${league} today".
           2. Search for "${league} injury report today ${new Date().toLocaleDateString()}".
           3. Verify lines are current.`;

    const prompt = `
      Act as a Senior Machine Learning Engineer and Betting Model Architect.

      Task: ${isPlayerSearch ? `Analyze betting markets for the player "${filters}"` : `Generate 5 distinct, mathematically optimized parlay recommendations for the ${league}`}.

      Parameters:
      - Risk Tolerance: ${risk}
      - Context/Search: ${filters || "None"}
      - Current Date: ${new Date().toLocaleDateString()}

      CRITICAL INSTRUCTION - LIVE DATA & CROSS-BOOK COMPARISON:
      You MUST use the 'googleSearch' tool to find REAL-TIME, LIVE odds.
      You MUST specifically look for lines on DraftKings (DK), FanDuel (FD), and PrizePicks (PP).

      ${searchInstruction}

      Optimization Process:
      1. Identify +EV spots where lines might be soft.
      2. If a specific player was searched, your "legs" should be the different prop types available for that player (e.g. Points, Rebounds).
      3. If generating parlays, build 3-12 leg parlays mixing safe and risky plays.

      DATA FORMATTING FOR 'RATIONALE':
      In the 'rationale' field of the JSON, you MUST explicitly state the lines found at different books. 
      Format: "DK: -110 | FD: -120 | PP: 24.5". 
      Highlight which book has the best line.

      OUTPUT FORMAT RULES:
      1. Your final response must be a SINGLE VALID JSON object.
      2. DO NOT include any text before the opening brace '{'.
      3. DO NOT include any text, markdown, or headers (like '## Navigation') after the closing brace '}'.
      4. DO NOT wrap the output in markdown code blocks.

      JSON Structure:
      {
        "recommendations": [
          {
            "id": "string",
            "summary": "string (Explain the strategy and mention the best book found)",
            "totalOdds": number,
            "jointProbAdjusted": number,
            "expectedValue": number,
            "kellyStake": number,
            "correlationScore": number,
            "varianceScore": number,
            "timestamp": "string",
            "legs": [
              {
                "playerId": "string",
                "playerName": "string",
                "team": "string",
                "opponent": "string",
                "statType": "string",
                "line": number,
                "prediction": "Over" | "Under",
                "bookOdds": number,
                "modelProb": number,
                "impliedProb": number,
                "edge": number,
                "rationale": "string (MUST INCLUDE BOOK COMPARISON e.g. 'DK: -110 | FD: -130')"
              }
            ]
          }
        ]
      }
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      }
    });

    let text = response.text;
    if (!text) throw new Error("No data returned from model");

    // Clean potential markdown code blocks
    text = text.replace(/```json/g, '').replace(/```/g, '');

    // Robust JSON extraction
    const startIndex = text.indexOf('{');
    const endIndex = text.lastIndexOf('}');

    if (startIndex === -1 || endIndex === -1) {
        console.error("Raw AI Response (Failed to find JSON):", text);
        throw new Error("AI output did not contain valid JSON structure. It likely returned a text summary.");
    }

    const jsonString = text.substring(startIndex, endIndex + 1);

    let parsed;
    try {
        parsed = JSON.parse(jsonString);
    } catch (e) {
        console.error("JSON Parse Error:", e);
        throw new Error("Failed to parse AI response as JSON.");
    }

    // Sanitize and validate data types
    const sanitizedRecommendations: ParlayRecommendation[] = (parsed.recommendations || []).map((rec: any, index: number) => ({
        id: rec.id || `parlay-${index}-${Date.now()}`,
        summary: rec.summary || "No summary provided.",
        totalOdds: Number(rec.totalOdds) || 0,
        jointProbAdjusted: Number(rec.jointProbAdjusted) || 0,
        expectedValue: Number(rec.expectedValue) || 0,
        kellyStake: Number(rec.kellyStake) || 0,
        correlationScore: Number(rec.correlationScore) || 0,
        varianceScore: Number(rec.varianceScore) || 0,
        timestamp: rec.timestamp || new Date().toISOString(),
        legs: (rec.legs || []).map((leg: any) => ({
            playerId: leg.playerId || "unknown",
            playerName: leg.playerName || "Unknown Player",
            team: leg.team || "N/A",
            opponent: leg.opponent || "N/A",
            statType: leg.statType || "Prop",
            line: Number(leg.line) || 0,
            prediction: leg.prediction || "Over",
            bookOdds: Number(leg.bookOdds) || -110,
            modelProb: Number(leg.modelProb) || 0.5,
            impliedProb: Number(leg.impliedProb) || 0.5,
            edge: Number(leg.edge) || 0,
            rationale: leg.rationale || "Analysis unavailable"
        }))
    }));

    return sanitizedRecommendations;

  } catch (error) {
    console.error("Gemini Service Error:", error);
    throw error;
  }
};

import React, { useMemo } from 'react';
import { ParlayRecommendation, BetLeg } from '../types';
import { TrendingUp, ShieldAlert, Activity, ChevronRight, BarChart3, Globe } from './Icons';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer, AreaChart, Area, XAxis, YAxis, CartesianGrid } from 'recharts';

interface ParlayCardProps {
  parlay: ParlayRecommendation;
  index: number;
}

const formatOdds = (odds: number) => (odds > 0 ? `+${odds}` : `${odds}`);

const LegRow: React.FC<{ leg: BetLeg }> = ({ leg }) => (
  <div className="flex flex-col p-3 bg-gray-900 rounded border border-gray-800 mb-2 hover:border-gray-700 transition-colors">
    <div className="flex flex-col sm:flex-row sm:items-center justify-between">
        <div className="flex items-center gap-3">
        <div className={`w-1 h-8 rounded-full ${leg.prediction === 'Over' ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>
        <div>
            <div className="font-semibold text-gray-200">{leg.playerName}</div>
            <div className="text-xs text-gray-400 font-mono">
            {leg.team} vs {leg.opponent} • <span className="text-gray-300">{leg.statType}</span>
            </div>
        </div>
        </div>

        <div className="flex items-center justify-between sm:justify-end gap-4 mt-2 sm:mt-0">
            <div className="text-right">
                <div className="text-sm text-gray-400">Line</div>
                <div className="font-mono font-medium text-white">
                    {leg.prediction === 'Over' ? 'O' : 'U'} {leg.line}
                </div>
            </div>
            <div className="text-right hidden sm:block">
                <div className="text-sm text-gray-400">Model %</div>
                <div className="font-mono font-bold text-emerald-400">{((leg.modelProb || 0) * 100).toFixed(1)}%</div>
            </div>
            <div className="text-right">
                <div className="text-sm text-gray-400">Edge</div>
                <div className="font-mono text-emerald-400 font-bold">+{ (leg.edge || 0).toFixed(1)}%</div>
            </div>
        </div>
    </div>

    {/* Rationale / Book Comparison Section */}
    {leg.rationale && (
        <div className="mt-2 pt-2 border-t border-gray-800 flex items-start gap-2">
            <Globe size={12} className="text-blue-400 mt-0.5 shrink-0" />
            <p className="text-xs text-gray-400 font-mono leading-relaxed">
                <span className="text-blue-400 font-semibold mr-1">Book Scan:</span> 
                {leg.rationale}
            </p>
        </div>
    )}
  </div>
);

export const ParlayCard: React.FC<ParlayCardProps> = ({ parlay, index }) => {

  const riskColor = parlay.varianceScore > 7 ? 'text-rose-400' : parlay.varianceScore > 4 ? 'text-yellow-400' : 'text-emerald-400';
  const data = [
    { name: 'Model Prob', value: (parlay.jointProbAdjusted || 0) * 100 },
    { name: 'Risk', value: 100 - ((parlay.jointProbAdjusted || 0) * 100) },
  ];
  const COLORS = ['#10b981', '#374151'];

  // Generate simulated historical data for the chart based on current stats
  const historyData = useMemo(() => {
    const history = [];
    const baseEv = parlay.expectedValue || 0;
    const baseStake = parlay.kellyStake || 0;

    // Simulate 12 data points (e.g., last 6 hours, 30 min intervals)
    for (let i = 12; i >= 0; i--) {
        // Create realistic fluctuation
        const timeOffset = i * 30; // minutes
        const noise = (Math.sin(i) * 2) + ((Math.random() - 0.5) * 1.5);

        // The further back, the more "different" it might be, converging to current
        let simEv = baseEv + (noise * (i / 8));
        let simStake = baseStake + (noise * (i / 15));

        // Clamping
        simEv = Math.max(0.5, simEv);
        simStake = Math.max(0.1, simStake);

        history.push({
            time: i === 0 ? 'Now' : `-${timeOffset}m`,
            ev: parseFloat(simEv.toFixed(1)),
            stake: parseFloat(simStake.toFixed(2))
        });
    }
    // Force last point to be exact current values
    history[history.length - 1].ev = baseEv;
    history[history.length - 1].stake = baseStake;

    return history;
  }, [parlay.expectedValue, parlay.kellyStake]);

  return (
    <div className="bg-gray-850 rounded-xl border border-gray-800 p-6 mb-6 shadow-xl relative overflow-hidden group">
      {/* Decorative Top Border */}
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-emerald-500 via-blue-500 to-purple-500 opacity-70"></div>

      <div className="flex flex-col lg:flex-row gap-6">

        {/* Left: Stats & Overview */}
        <div className="flex-1 min-w-0">
          <div className="flex justify-between items-start mb-4">
            <div>
              <div className="flex items-center gap-2 mb-1">
                <span className="bg-gray-800 text-gray-300 text-xs px-2 py-0.5 rounded font-mono uppercase tracking-wider">
                  Option #{index + 1}
                </span>
                <span className="text-emerald-400 text-xs font-mono flex items-center gap-1">
                   <Activity size={12} /> {(parlay.expectedValue || 0).toFixed(1)}% EV
                </span>
              </div>
              <h3 className="text-2xl font-bold text-white font-mono tracking-tight">
                {formatOdds(parlay.totalOdds)} PARLAY
              </h3>
            </div>

            <div className="text-right">
              <div className="text-xs text-gray-400 uppercase tracking-widest mb-1">Kelly Stake</div>
              <div className="text-xl font-mono font-bold text-blue-400">{(parlay.kellyStake || 0).toFixed(2)}%</div>
            </div>
          </div>

          <div className="mb-4 relative">
             <div className="max-h-[320px] overflow-y-auto pr-1 custom-scrollbar space-y-2 pb-2">
                {parlay.legs && parlay.legs.map((leg, i) => (
                  <LegRow key={i} leg={leg} />
                ))}
             </div>
             {/* Subtle gradient to hint more content if scrolling */}
             {parlay.legs && parlay.legs.length > 4 && (
                <div className="absolute bottom-0 left-0 right-0 h-6 bg-gradient-to-t from-gray-850 to-transparent pointer-events-none"></div>
             )}
          </div>

          <div className="bg-gray-900/50 p-3 rounded border border-gray-800/50">
             <p className="text-sm text-gray-400 italic">
                <span className="text-blue-400 font-semibold not-italic mr-2">Analysis:</span>
                {parlay.summary}
             </p>
          </div>

          {/* Historical Performance Chart */}
          <div className="mt-4 pt-4 border-t border-gray-800">
             <div className="flex items-center gap-2 mb-3">
                 <BarChart3 size={14} className="text-gray-500" />
                 <h4 className="text-xs text-gray-400 uppercase tracking-wider font-semibold">Value Tracking (Last 6h)</h4>
             </div>
             <div className="h-40 w-full bg-gray-900/20 rounded-lg border border-gray-800/50 p-2">
                 <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={historyData}>
                        <defs>
                            <linearGradient id="colorEv" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#10b981" stopOpacity={0.3}/>
                                <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                            </linearGradient>
                            <linearGradient id="colorStake" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                                <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#374151" vertical={false} opacity={0.5} />
                        <XAxis 
                            dataKey="time" 
                            tick={{fontSize: 10, fill: '#6b7280'}} 
                            axisLine={false}
                            tickLine={false}
                            interval={2}
                        />
                        <YAxis hide domain={['auto', 'auto']} />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#1f2937', borderColor: '#374151', fontSize: '12px', borderRadius: '4px' }}
                            itemStyle={{ padding: 0 }}
                            labelStyle={{ color: '#9ca3af', marginBottom: '4px' }}
                        />
                        <Area 
                            type="monotone" 
                            dataKey="ev" 
                            name="Exp. Value %"
                            stroke="#10b981" 
                            fillOpacity={1} 
                            fill="url(#colorEv)" 
                            strokeWidth={2}
                        />
                         <Area 
                            type="monotone" 
                            dataKey="stake" 
                            name="Kelly Stake %"
                            stroke="#3b82f6" 
                            fillOpacity={1} 
                            fill="url(#colorStake)" 
                            strokeWidth={2}
                            strokeDasharray="4 2"
                        />
                    </AreaChart>
                 </ResponsiveContainer>
             </div>
          </div>
        </div>

        {/* Right: Technical Metrics Visualization */}
        <div className="w-full lg:w-64 bg-gray-900 rounded-lg p-4 border border-gray-800 flex flex-col justify-between shrink-0">
           <div>
               <h4 className="text-xs text-gray-400 uppercase tracking-wider font-semibold mb-3 flex items-center gap-2">
                   <TrendingUp size={14} /> Risk Profile
               </h4>

               <div className="h-32 w-full relative">
                 <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie
                            data={data}
                            cx="50%"
                            cy="50%"
                            innerRadius={30}
                            outerRadius={45}
                            fill="#8884d8"
                            paddingAngle={5}
                            dataKey="value"
                            startAngle={90}
                            endAngle={-270}
                        >
                        {data.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                        ))}
                        </Pie>
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#1f2937', borderColor: '#374151', fontSize: '12px' }}
                            itemStyle={{ color: '#e5e7eb' }}
                        />
                    </PieChart>
                 </ResponsiveContainer>
                 <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                     <span className="text-xs font-mono text-emerald-400 font-bold">{((parlay.jointProbAdjusted || 0) * 100).toFixed(0)}%</span>
                 </div>
               </div>
           </div>

           <div className="space-y-3 mt-2">
               <div className="flex justify-between items-center text-xs">
                   <span className="text-gray-500">Correlation</span>
                   <span className="text-gray-300 font-mono">{((parlay.correlationScore || 0) * 100).toFixed(0)}/100</span>
               </div>
               <div className="w-full bg-gray-800 h-1 rounded overflow-hidden">
                   <div className="bg-blue-500 h-full" style={{ width: `${(parlay.correlationScore || 0) * 100}%` }}></div>
               </div>

               <div className="flex justify-between items-center text-xs">
                   <span className="text-gray-500">Variance Score</span>
                   <span className={`${riskColor} font-mono`}>{(parlay.varianceScore || 0).toFixed(1)}/10</span>
               </div>
               <div className="w-full bg-gray-800 h-1 rounded overflow-hidden">
                   <div className={`h-full ${parlay.varianceScore > 7 ? 'bg-rose-500' : 'bg-emerald-500'}`} style={{ width: `${(parlay.varianceScore || 0) * 10}%` }}></div>
               </div>
           </div>
        </div>

      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { League, RiskLevel, ParlayRecommendation } from "../types";

export const generateParlays = async (
  league: League,
  risk: RiskLevel,
  filters: string
): Promise<ParlayRecommendation[]> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API Key not found in environment variables.");
    }

    const ai = new GoogleGenAI({ apiKey });

    // Using gemini-2.5-pro for its ability to use Google Search tools (Grounding)
    const modelId = "gemini-2.5-pro";

    const isPlayerSearch = filters && filters.length > 2;

    const searchInstruction = isPlayerSearch
        ? `SEARCH STRATEGY (PLAYER FOCUS):
           1. Search for "${filters} player props today DraftKings FanDuel PrizePicks".
           2. Search for "${filters} lines comparison DraftKings vs FanDuel vs PrizePicks".
           3. Look specifically for discrepancies (e.g., line differences like 24.5 vs 23.5) between these three books.
           4. Find the live lines for Points, Rebounds, Assists, and Threes.`
        : `SEARCH STRATEGY (GENERAL PARLAY):
           1. Search for "${league} player props today DraftKings FanDuel PrizePicks".
           2. Search for "best ${league} prop bets today discrepancies DraftKings vs FanDuel".
           3. Search for "PrizePicks ${league} projections today".
           4. Compare lines across DraftKings, FanDuel, and PrizePicks to find arbitrage or soft lines.`;

    const prompt = `
      Act as a Senior Machine Learning Engineer and Betting Model Architect.

      Task: ${isPlayerSearch ? `Analyze betting markets for the player "${filters}"` : `Generate 5 distinct, mathematically optimized parlay recommendations for the ${league}`}.

      Parameters:
      - Risk Tolerance: ${risk}
      - Context/Search: ${filters || "None"}
      - Current Date: ${new Date().toLocaleDateString()}

      CRITICAL INSTRUCTION - LIVE DATA & CROSS-BOOK COMPARISON:
      You MUST use the 'googleSearch' tool to find REAL-TIME, LIVE odds from DraftKings (DK), FanDuel (FD), and PrizePicks (PP).
      Your primary goal is to find value by comparing these three specific books.

      ${searchInstruction}

      Optimization Process:
      1. Identify +EV spots where lines differ between books (e.g. DK has -110 for O20.5, while FD has -130 for O20.5, or PP is at 19.5).
      2. If a specific player was searched, your "legs" should be the different prop types available for that player (e.g. Points, Rebounds) showing the best line found.
      3. If generating parlays, build 3-12 leg parlays mixing safe and risky plays based on these cross-book findings.

      DATA FORMATTING FOR 'RATIONALE':
      In the 'rationale' field of the JSON, you MUST explicitly state the lines found at different books. 
      Format: "DK: -110 | FD: -120 | PP: 20.5". 
      Highlight the discrepancy or why the chosen line is the best value.

      OUTPUT FORMAT RULES:
      1. Your final response must be a SINGLE VALID JSON object.
      2. DO NOT include any text before the opening brace '{'.
      3. DO NOT include any text, markdown, or headers (like '## Navigation') after the closing brace '}'.
      4. DO NOT wrap the output in markdown code blocks.

      JSON Structure:
      {
        "recommendations": [
          {
            "id": "string",
            "summary": "string (Explain the strategy and mention the best book found)",
            "totalOdds": number,
            "jointProbAdjusted": number,
            "expectedValue": number,
            "kellyStake": number,
            "correlationScore": number,
            "varianceScore": number,
            "timestamp": "string",
            "legs": [
              {
                "playerId": "string",
                "playerName": "string",
                "team": "string",
                "opponent": "string",
                "statType": "string",
                "line": number,
                "prediction": "Over" | "Under",
                "bookOdds": number,
                "modelProb": number,
                "impliedProb": number,
                "edge": number,
                "rationale": "string (MUST INCLUDE BOOK COMPARISON e.g. 'DK: -110 | FD: -130')"
              }
            ]
          }
        ]
      }
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      }
    });

    let text = response.text;
    if (!text) throw new Error("No data returned from model");

    // Clean potential markdown code blocks
    text = text.replace(/```json/g, '').replace(/```/g, '');

    // Robust JSON extraction
    const startIndex = text.indexOf('{');
    const endIndex = text.lastIndexOf('}');

    if (startIndex === -1 || endIndex === -1) {
        console.error("Raw AI Response (Failed to find JSON):", text);
        throw new Error("AI output did not contain valid JSON structure. It likely returned a text summary.");
    }

    const jsonString = text.substring(startIndex, endIndex + 1);

    let parsed;
    try {
        parsed = JSON.parse(jsonString);
    } catch (e) {
        console.error("JSON Parse Error:", e);
        throw new Error("Failed to parse AI response as JSON.");
    }

    // Sanitize and validate data types
    const sanitizedRecommendations: ParlayRecommendation[] = (parsed.recommendations || []).map((rec: any, index: number) => ({
        id: rec.id || `parlay-${index}-${Date.now()}`,
        summary: rec.summary || "No summary provided.",
        totalOdds: Number(rec.totalOdds) || 0,
        jointProbAdjusted: Number(rec.jointProbAdjusted) || 0,
        expectedValue: Number(rec.expectedValue) || 0,
        kellyStake: Number(rec.kellyStake) || 0,
        correlationScore: Number(rec.correlationScore) || 0,
        varianceScore: Number(rec.varianceScore) || 0,
        timestamp: rec.timestamp || new Date().toISOString(),
        legs: (rec.legs || []).map((leg: any) => ({
            playerId: leg.playerId || "unknown",
            playerName: leg.playerName || "Unknown Player",
            team: leg.team || "N/A",
            opponent: leg.opponent || "N/A",
            statType: leg.statType || "Prop",
            line: Number(leg.line) || 0,
            prediction: leg.prediction || "Over",
            bookOdds: Number(leg.bookOdds) || -110,
            modelProb: Number(leg.modelProb) || 0.5,
            impliedProb: Number(leg.impliedProb) || 0.5,
            edge: Number(leg.edge) || 0,
            rationale: leg.rationale || "Analysis unavailable"
        }))
    }));

    return sanitizedRecommendations;

  } catch (error) {
    console.error("Gemini Service Error:", error);
    throw error;
  }
};

