          <div className="mb-4 relative">
             <div className="max-h-[320px] overflow-y-auto pr-1 custom-scrollbar space-y-2 pb-2">
                {parlay.legs && parlay.legs.map((leg, i) => (
                  <LegRow key={i} leg={leg} />
