    // Using gemini-2.5-pro for its ability to use Google Search tools (Grounding)
    const modelId = "gemini-2.5-pro";

    const isPlayerSearch = filters && filters.length > 2;

    const searchInstruction = isPlayerSearch
        ? `SEARCH STRATEGY (PLAYER PROFILE MODE):
           1. Search for "${filters} player props today DraftKings FanDuel PrizePicks Underdog Fantasy Chalkboard".
           2. Search for "${filters} stats last 10 games".
           3. Search for "${filters} vs opponent matchup data".
           4. CRITICAL: Fetch ALL available market lines for this player: Points, Rebounds, Assists, 3-Pointers, P+R+A (Points+Rebounds+Assists).
           5. For EACH market, find the best line available across books (DraftKings, FanDuel, PrizePicks, Underdog, Chalkboard).`
        : `SEARCH STRATEGY (PERFECT PARLAY CURATION):
           1. Search for "best ${league} player prop correlations today" (e.g. QB/WR stacks, teammates).
           2. Search for "${league} players with 80% hit rate last 10 games props".
           3. Compare lines across DraftKings, FanDuel, PrizePicks, Underdog Fantasy, and Chalkboard to find the 'softest' number.
           4. Look for "Ladder" opportunities where a player is consistently crushing their line.`;

    const prompt = `
      Act as an Elite Algorithmic Betting Engine & Chief Mathematician.

      MODE: ${isPlayerSearch ? "SINGLE PLAYER DEEP DIVE PROFILE" : "OPTIMIZED PARLAY GENERATION"}

      Context:
      - League: ${league}
      - User Focus: ${filters || "General Optimization"}
      - Strategy: ${risk === RiskLevel.HIGH ? "Correlated Aggressive (High Variance)" : "High-Floor Safety (Low Variance)"}

      ### ADVANCED MATHEMATICAL & STATISTICAL FRAMEWORK INSTRUCTIONS:
      You are a rigorous statistical engine. You must apply the following concepts to derive "True Probability" vs "Implied Probability":

      1. **Bayesian Inference & Updating**: 
         - **Prior**: The Bookmaker's Implied Probability (from live odds).
         - **Likelihood Function**: Derived from recent form (L10/L20), opponent defensive efficiency (DVOA/Def Rating), and matchup-specific variables.
         - **Posterior**: Your final calculated 'Model Probability'. Update the prior heavily if signal-to-noise ratio in recent data is high.

      2. **Distribution Modeling (Poisson, Skellam, Negative Binomial)**:
         - **Counting Stats (Pts, Rebs, Asts)**: Model using **Poisson** or **Negative Binomial** distributions (to account for over-dispersion).
         - **Spread/Margins**: Use **Skellam Distribution** logic.
         - **Yardage/Continuous**: Fit to a **Log-Normal** distribution to account for skew.
         - Calculate the Cumulative Density Function (CDF) area beyond the line 'k'.

      3. **Multivariate Correlation & Copula Functions** (MANDATORY FOR PARLAYS):
         - **Do NOT** assume independence. P(A and B) != P(A) * P(B).
         - Construct a dependency structure using **Gaussian Copulas**.
         - If Leg A (QB Passing Yards) and Leg B (WR Receiving Yards) have a correlation coefficient $\rho > 0.5$, the joint probability MUST be boosted significantly.
         - Penalize "Anti-Correlated" legs (e.g., RB Rushing Yards Over + QB Passing Yards Over in a low total game).

      4. **Time-Series Analysis & Exponential Smoothing**:
         - Apply **Exponential Moving Averages (EMA)** to player stats. Recent games (t-1, t-2) carry more weight ($w$) than older games.
         - Use **ARIMA** (Auto-Regressive Integrated Moving Average) intuition to detect if a player is trending up or reverting to the mean.

      5. **Game Theory & Market Efficiency**:
         - **Nash Equilibrium**: Identify lines where the market has likely over-adjusted to public sentiment (fading the public).
         - **Arbitrage/Line Shopping**: If PrizePicks is 24.5 and DraftKings is 26.5, exploit the **Middle** or the **Soft Line**.
         - **Utility Theory**: Optimize choices not just for raw EV, but for **Expected Utility (Log-Wealth)** to avoid ruin.

      6. **Kelly Criterion & Portfolio Optimization**:
         - **Stake Sizing**: Calculate 'kellyStake' = (bp - q) / b.
         - **Fractional Kelly**: Use 0.25x or 0.5x Kelly for high-variance/parlay bets to reduce Risk of Ruin.
         - **Sharpe Ratio**: Rank recommendations by (Expected Return / Standard Deviation).

      7. **Monte Carlo Simulation**:
         - Mentally simulate the game script 10,000 times based on pace/efficiency metrics to find the frequency of the outcome.

      CRITICAL DATA INSTRUCTIONS:
      1. USE LIVE TOOLS: You MUST use 'googleSearch' to find real-time lines from major sportsbooks and DFS platforms: **DraftKings (DK), FanDuel (FD), PrizePicks (PP), Underdog Fantasy (UD), and Chalkboard**.
      2. CROSS-BOOK CHECK: Highlight discrepancies (e.g., "Line discrepancy: DK -130, FD -110").

      OUTPUT FORMAT RULES:
      1. Return a SINGLE VALID JSON object.
      2. NO MARKDOWN formatting outside the JSON.
      3. JSON ONLY.

      JSON Structure:
      {
        "recommendations": [
          {
            "type": "parlay" | "player_profile",
            "id": "string",
            "summary": "string (Explain the math: 'Bayesian posterior indicates... Copula correlation boost...')",
            "totalOdds": number,
            "jointProbAdjusted": number,
            "expectedValue": number,
            "kellyStake": number,
            "correlationScore": number,
            "varianceScore": number,
            "timestamp": "string",
            "legs": [
              {
                "playerId": "string",
                "playerName": "string",
                "team": "string",
                "opponent": "string",
                "statType": "string",
                "line": number,
                "prediction": "Over" | "Under",
                "bookOdds": number,
                "modelProb": number,
                "impliedProb": number,
                "edge": number,
                "rationale": "string"
              }
            ]
          }
        ]
      }
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      }
    });

    let text = response.text;
    if (!text) throw new Error("No data returned from model");

    text = text.replace(/```json/g, '').replace(/```/g, '');

    const startIndex = text.indexOf('{');
    const endIndex = text.lastIndexOf('}');

    if (startIndex === -1 || endIndex === -1) {
        console.error("Raw AI Response (Failed to find JSON):", text);
        throw new Error("AI output did not contain valid JSON structure.");
    }

    const jsonString = text.substring(startIndex, endIndex + 1);

    let parsed;
    try {
        parsed = JSON.parse(jsonString);
    } catch (e) {
        console.error("JSON Parse Error:", e);
        throw new Error("Failed to parse AI response as JSON.");
    }

    const sanitizedRecommendations: ParlayRecommendation[] = (parsed.recommendations || []).map((rec: any, index: number) => ({
        type: rec.type || (isPlayerSearch ? 'player_profile' : 'parlay'),
        id: rec.id || `rec-${index}-${Date.now()}`,
        summary: rec.summary || "High correlation optimized bundle.",
        totalOdds: Number(rec.totalOdds) || 0,
        jointProbAdjusted: Number(rec.jointProbAdjusted) || 0,
        expectedValue: Number(rec.expectedValue) || 0,
        kellyStake: Number(rec.kellyStake) || 0,
        correlationScore: Number(rec.correlationScore) || 0,
        varianceScore: Number(rec.varianceScore) || 0,
        timestamp: rec.timestamp || new Date().toISOString(),
        legs: (rec.legs || []).map((leg: any) => ({
            playerId: leg.playerId || "unknown",
            playerName: leg.playerName || "Unknown Player",
            team: leg.team || "N/A",
            opponent: leg.opponent || "N/A",
            statType: leg.statType || "Prop",
            line: Number(leg.line) || 0,
            prediction: leg.prediction || "Over",
            bookOdds: Number(leg.bookOdds) || -110,
            modelProb: Number(leg.modelProb) || 0.60,
            impliedProb: Number(leg.impliedProb) || 0.55,
            edge: Number(leg.edge) || 0,
            rationale: leg.rationale || "Strong L10 Trend"
        }))
    }));

    return sanitizedRecommendations;

  } catch (error) {
    console.error("Gemini Service Error:", error);
    throw error;
  }
};

