import { GoogleGenAI } from "@google/genai";
import { League, RiskLevel, ParlayRecommendation } from "../types";

export const generateParlays = async (
  league: League,
  risk: RiskLevel,
  filters: string
): Promise<ParlayRecommendation[]> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API Key not found in environment variables.");
    }

    const ai = new GoogleGenAI({ apiKey });

    // Switch to flash to mitigate 429 Rate Limit errors and improve speed.
    // The previous 'gemini-2.5-pro' is prone to stricter quotas.
    const modelId = "gemini-2.5-flash";

    const isPlayerSearch = filters && filters.length > 2;
    const isDailyTop3 = !filters || filters.length === 0;

    let searchInstruction = "";

    if (isPlayerSearch) {
        searchInstruction = `SEARCH STRATEGY (PLAYER PROFILE MODE):
           1. Search for "${filters} player props today DraftKings FanDuel PrizePicks Underdog Fantasy Chalkboard".
           2. Search for "${filters} stats last 10 games".
           3. Search for "${filters} vs opponent matchup data".
           4. CRITICAL: Fetch ALL available market lines for this player: Points, Rebounds, Assists, 3-Pointers, P+R+A.
           5. For EACH market, find the best line available across books.`;
    } else {
        // Daily Top 3 Strategy
        searchInstruction = `SEARCH STRATEGY (DAILY TOP 3 VALUE PACK):
           1. Search for "best ${league} player prop picks today [Current Date]".
           2. Search for "highest EV ${league} player props today oddsjam props.cash".
           3. Search for "player prop discrepancies DraftKings vs PrizePicks today ${league}".
           4. Identify 9 specific players with distinct advantages (e.g., injury replacements, blowout trends, defense vs position).
           5. Group them into 3 distinct correlated parlays.`;
    }

    const prompt = `
      Act as an Elite Algorithmic Betting Engine & Chief Mathematician.

      MODE: ${isPlayerSearch ? "SINGLE PLAYER DEEP DIVE PROFILE" : "DAILY TOP 3 (3-LEG PARLAYS)"}

      Context:
      - League: ${league}
      - User Focus: ${filters || "Daily System Picks (Best Value Today)"}
      - Strategy: ${risk === RiskLevel.HIGH ? "Correlated Aggressive (High Variance)" : "High-Floor Safety (Low Variance)"}

      ### EXECUTION CONSTRAINTS (CRITICAL):
      ${isDailyTop3 ? `
      1. **STRUCTURE**: You MUST return exactly THREE (3) distinct parlays.
      2. **LEGS**: Each parlay MUST have exactly THREE (3) legs.
      3. **TIMING**: All picks must be for games happening TODAY.
      4. **ODDS**: Use real-time odds found via Google Search.
      ` : ''}

      ### ADVANCED MATHEMATICAL & STATISTICAL FRAMEWORK INSTRUCTIONS:
      You are a rigorous statistical engine. You must apply the following concepts to derive "True Probability" vs "Implied Probability":

      1. **Bayesian Inference & Updating**: 
         - **Prior**: The Bookmaker's Implied Probability (from live odds).
         - **Likelihood Function**: Derived from recent form (L10/L20), opponent defensive efficiency (DVOA/Def Rating).
         - **Posterior**: Your final calculated 'Model Probability'.

      2. **Distribution Modeling**:
         - **Counting Stats**: Model using **Poisson** or **Negative Binomial**.
         - **Spread/Margins**: Use **Skellam Distribution**.
         - **Yardage**: Fit to a **Log-Normal** distribution.

      3. **Multivariate Correlation & Copula Functions**:
         - **Do NOT** assume independence. P(A and B) != P(A) * P(B).
         - Construct a dependency structure using **Gaussian Copulas**.
         - If Leg A and Leg B have a correlation coefficient $\rho > 0.5$, boost joint probability.

      4. **Game Theory & Market Efficiency**:
         - **Nash Equilibrium**: Identify lines where the market has likely over-adjusted.
         - **Arbitrage/Line Shopping**: Exploit differences between DraftKings, FanDuel, and PrizePicks.

      5. **Kelly Criterion**:
         - **Stake Sizing**: Calculate 'kellyStake' based on your calculated Edge.

      CRITICAL DATA INSTRUCTIONS:
      1. USE LIVE TOOLS: You MUST use 'googleSearch' to find real-time lines.
      2. CROSS-BOOK CHECK: Highlight discrepancies.

      ### OUTPUT FORMAT RULES (STRICT):
      1. **RETURN RAW JSON ONLY**.
      2. **NO MARKDOWN**. Do not use \`\`\`json blocks.
      3. **NO CONVERSATIONAL TEXT**. Do not write "Here are the top picks...".
      4. **NO TABLES**.
      5. The output must start with '{' and end with '}'.

      JSON Structure:
      {
        "recommendations": [
          {
            "type": "parlay" | "player_profile",
            "id": "string",
            "summary": "string (Explain the math: 'Bayesian posterior indicates... Copula correlation boost...')",
            "totalOdds": number,
            "jointProbAdjusted": number,
            "expectedValue": number,
            "kellyStake": number,
            "correlationScore": number,
            "varianceScore": number,
            "timestamp": "string",
            "legs": [
              {
                "playerId": "string",
                "playerName": "string",
                "team": "string",
                "opponent": "string",
                "statType": "string",
                "line": number,
                "prediction": "Over" | "Under",
                "bookOdds": number,
                "modelProb": number,
                "impliedProb": number,
                "edge": number,
                "rationale": "string"
              }
            ]
          }
        ]
      }
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        // Note: responseMimeType is NOT allowed when using tools like googleSearch.
        // We rely on the strict prompt to ensure JSON output.
      }
    });

    let text = response.text;
    if (!text) throw new Error("No data returned from model");

    // Clean markdown if present (despite strict instructions)
    text = text.replace(/```json/g, '').replace(/```/g, '');

    const startIndex = text.indexOf('{');
    const endIndex = text.lastIndexOf('}');

    if (startIndex === -1 || endIndex === -1) {
        console.error("Raw AI Response (Failed to find JSON):", text);
        // If the model returned a table or text instead of JSON, we can't parse it.
        throw new Error("Live data stream format error. The model returned unstructured text instead of JSON. Please try again.");
    }

    const jsonString = text.substring(startIndex, endIndex + 1);

    let parsed;
    try {
        parsed = JSON.parse(jsonString);
    } catch (e) {
        console.error("JSON Parse Error:", e);
        throw new Error("Failed to parse AI response as JSON.");
    }

    const sanitizedRecommendations: ParlayRecommendation[] = (parsed.recommendations || []).map((rec: any, index: number) => ({
        type: rec.type || (isPlayerSearch ? 'player_profile' : 'parlay'),
        id: rec.id || `rec-${index}-${Date.now()}`,
        summary: rec.summary || "High correlation optimized bundle.",
        totalOdds: Number(rec.totalOdds) || 0,
        jointProbAdjusted: Number(rec.jointProbAdjusted) || 0,
        expectedValue: Number(rec.expectedValue) || 0,
        kellyStake: Number(rec.kellyStake) || 0,
        correlationScore: Number(rec.correlationScore) || 0,
        varianceScore: Number(rec.varianceScore) || 0,
        timestamp: rec.timestamp || new Date().toISOString(),
        legs: (rec.legs || []).map((leg: any) => ({
            playerId: leg.playerId || "unknown",
            playerName: leg.playerName || "Unknown Player",
            team: leg.team || "N/A",
            opponent: leg.opponent || "N/A",
            statType: leg.statType || "Prop",
            line: Number(leg.line) || 0,
            prediction: leg.prediction || "Over",
            bookOdds: Number(leg.bookOdds) || -110,
            modelProb: Number(leg.modelProb) || 0.60,
            impliedProb: Number(leg.impliedProb) || 0.55,
            edge: Number(leg.edge) || 0,
            rationale: leg.rationale || "Strong L10 Trend"
        }))
    }));

    return sanitizedRecommendations;

  } catch (error: any) {
    console.error("Gemini Service Error:", error);

    // Graceful 429 Handling
    if (error.status === 429 || (error.message && error.message.includes('429')) || (error.message && error.message.includes('quota'))) {
         throw new Error("Rate Limit Exceeded: The system is under heavy load. The auto-refresh interval will be paused briefly.");
    }

    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { generateParlays } from './services/geminiService';
import { League, RiskLevel, UserInputState, ParlayRecommendation } from './types';
import { InputForm } from './components/InputForm';
import { ParlayCard } from './components/ParlayCard';
import { PlayerProfileCard } from './components/PlayerProfileCard';
import { LoadingScreen } from './components/LoadingScreen';
import { LandingPage } from './components/LandingPage';
import { BarChart3, ShieldAlert, Home, Zap } from './components/Icons';

function App() {
  const [showLanding, setShowLanding] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [recommendations, setRecommendations] = useState<ParlayRecommendation[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<UserInputState>({
    league: League.NBA,
    riskLevel: RiskLevel.MEDIUM,
    bankroll: 1000,
    filters: ''
  });

  // Auto-trigger generation when entering the terminal
  useEffect(() => {
    if (!showLanding && recommendations.length === 0 && !isLoading) {
      console.log("System: Initializing Daily Top 3...");
      handleGenerate(false);
    }
  }, [showLanding]);

  // Auto-refresh logic (Always Active)
  // Increased to 60 seconds to avoid 429 Rate Limit errors
  useEffect(() => {
    const intervalId = setInterval(() => {
      if (!isLoading && !showLanding) {
        console.log("System: Executing scheduled background data sync...");
        handleGenerate(true);
      }
    }, 60000); // 60 seconds refresh cycle

    return () => clearInterval(intervalId);
  }, [isLoading, formData, showLanding]);

  const handleGenerate = async (isBackground = false, overrideParams?: UserInputState) => {
    setIsLoading(true);
    // Don't clear error on background refresh if it's already showing a rate limit, so user can see it
    if (!isBackground) setError(null);

    // Use override params if provided, otherwise current state
    const params = overrideParams || formData;

    // Only clear previous results if it's a manual action, not a background update
    if (!isBackground) {
        setRecommendations([]);
    }

    try {
      const results = await generateParlays(params.league, params.riskLevel, params.filters);
      setRecommendations(results);
      setError(null); // Clear error on success
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : "An unexpected error occurred.";
      setError(errorMessage);

      // If we get a rate limit error during background refresh, we might want to log it but not clear the UI
      if (isBackground) {
        console.warn("Background sync failed:", errorMessage);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handlePlayerClick = (playerName: string) => {
    // Scroll to top
    window.scrollTo({ top: 0, behavior: 'smooth' });

    // Update state to reflect the new search
    const newParams = { ...formData, filters: playerName };
    setFormData(newParams);

    // Trigger generation with new params immediately
    handleGenerate(false, newParams);
  };

  if (showLanding) {
    return (
        <LandingPage 
            onEnter={() => setShowLanding(false)} 
            hasActiveSession={recommendations.length > 0 || formData.filters !== ''}
        />
    );
  }

  // Determine header text
  const isDailyPicks = !formData.filters && recommendations.length > 0;

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans selection:bg-emerald-500/30">
      {/* Header */}
      <header className="border-b border-gray-800 bg-gray-900/50 backdrop-blur sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer hover:opacity-80 transition-opacity" onClick={() => setShowLanding(true)}>
            <div className="bg-emerald-500/10 p-2 rounded border border-emerald-500/20">
              <BarChart3 className="text-emerald-500" size={24} />
            </div>
            <div>
              <h1 className="text-lg font-bold text-white tracking-tight">PRR <span className="text-gray-500 text-sm font-normal">| Parlay Recommendation Robot</span></h1>
              <div className="text-[10px] font-mono text-emerald-400 uppercase tracking-widest">v1.1.0 • STATS ENGINE UPGRADED</div>
            </div>
          </div>

          {/* Mobile Home Button */}
          <button 
             onClick={() => setShowLanding(true)}
             className="md:hidden p-2 text-gray-400 hover:text-white"
             title="Return Home"
          >
             <Home size={20} />
          </button>

          {/* Desktop Nav */}
          <div className="hidden md:flex items-center gap-6 text-sm text-gray-400">

             {/* Home Button (Desktop) */}
             <button 
                onClick={() => setShowLanding(true)}
                className="flex items-center gap-2 px-3 py-1.5 rounded-lg hover:bg-gray-800 hover:text-white transition-all group"
             >
                <Home size={16} className="text-gray-500 group-hover:text-emerald-400 transition-colors" />
                <span className="font-mono text-xs font-medium uppercase tracking-wider">Exit Terminal</span>
             </button>

             <div className="h-4 w-px bg-gray-800"></div>

             <span className="flex items-center gap-2 text-emerald-400 font-medium">
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div> 
                Live Data Stream Active
             </span>
             <span className="font-mono">LATENCY: 42ms</span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Intro / Dashboard */}
        <div className="mb-8">
          <InputForm 
            formData={formData} 
            setFormData={setFormData} 
            onSubmit={() => handleGenerate(false)} 
            isLoading={isLoading}
          />
        </div>

        {/* Results Area */}
        <div className="space-y-6">
          {error && (
            <div className="bg-rose-950/30 border border-rose-900 text-rose-200 p-4 rounded-lg flex items-center gap-3">
              <ShieldAlert size={20} />
              <div>
                <p className="font-bold">System Error</p>
                <p className="text-sm opacity-80">{error}</p>
              </div>
            </div>
          )}

          {recommendations.length > 0 && (
             <div className="flex items-center justify-between mb-4 animate-fadeIn">
               <div>
                  <h3 className="text-xl font-bold text-white flex items-center gap-2">
                    {recommendations[0].type === 'player_profile' ? (
                       'Player Intelligence Report'
                    ) : isDailyPicks ? (
                       <><Zap className="text-yellow-400" fill="currentColor" size={20} /> TODAY'S TOP 3 VALUE PLAYS</>
                    ) : (
                       'Optimized Candidates'
                    )}
                  </h3>
                  {isDailyPicks && (
                    <p className="text-xs text-emerald-400 font-mono mt-1">
                      LIVE ALGORITHM PICKS • 3-LEG STRUCTURE • EXCLUSIVE
                    </p>
                  )}
               </div>
               <div className="flex items-center gap-4">
                 {isLoading && <span className="text-xs text-emerald-400 animate-pulse font-mono">SYNCING LIVE ODDS...</span>}
                 <span className="text-sm text-gray-500 font-mono hidden sm:block">Sorted by Utility Score (EV - Risk)</span>
               </div>
             </div>
          )}

          <div className="grid gap-6">
            {recommendations.map((item, index) => {
               if (item.type === 'player_profile') {
                   return <PlayerProfileCard key={item.id || index} data={item} />;
               }
               return (
                  <ParlayCard 
                    key={item.id || index} 
                    parlay={item} 
                    index={index} 
                    onPlayerClick={handlePlayerClick}
                  />
               );
            })}
          </div>

          {!isLoading && recommendations.length === 0 && !error && (
            <div className="text-center py-20 border border-dashed border-gray-800 rounded-xl">
              <div className="inline-block p-4 rounded-full bg-gray-900 mb-4">
                <BarChart3 className="text-gray-600" size={32} />
              </div>
              <h3 className="text-gray-400 font-medium text-lg">Initializing System...</h3>
              <p className="text-gray-600 max-w-md mx-auto mt-2">
                 Connecting to live odds providers and generating daily value picks.
              </p>
            </div>
          )}
        </div>
      </main>

      {/* Disclaimer Footer */}
      <footer className="border-t border-gray-900 mt-12 py-8 bg-gray-950">
        <div className="max-w-7xl mx-auto px-4 text-center">
            <p className="text-xs text-gray-600 max-w-2xl mx-auto leading-relaxed">
              DISCLAIMER: This system is for informational and entertainment purposes only. "PRR" uses simulated historical data and probability models which do not guarantee future results. Gambling involves risk. Please gamble responsibly. If you or someone you know has a gambling problem, call 1-800-GAMBLER.
            </p>
            <p className="text-[10px] text-gray-700 mt-4 font-mono">
              ENGINE: XGBoost v1.7.6 | DATA: SportRadar/Genius (Simulated) | LATENCY: 42ms
            </p>
        </div>
      </footer>

      {/* Only show full screen loader if we have no data to show yet. Background refreshes are silent/subtle. */}
      {isLoading && recommendations.length === 0 && <LoadingScreen />}
    </div>
  );
}

export default App;

