};

// --- Main Service Logic ---

const parseResponse = (text: string, isPlayerSearch: boolean): ParlayRecommendation[] => {
    let cleanedText = text.replace(/```json/g, '').replace(/```/g, '');
    const startIndex = cleanedText.indexOf('{');
    const endIndex = cleanedText.lastIndexOf('}');

    if (startIndex === -1 || endIndex === -1) {
        throw new Error("AI returned unstructured text.");
    }

    const jsonString = cleanedText.substring(startIndex, endIndex + 1);
    const parsed = JSON.parse(jsonString);

    return (parsed.recommendations || []).map((rec: any, index: number) => ({
        type: rec.type || (isPlayerSearch ? 'player_profile' : 'parlay'),
        id: rec.id || `rec-${index}-${Date.now()}`,
        summary: rec.summary || "Analysis generated.",
        totalOdds: Number(rec.totalOdds) || 0,
        jointProbAdjusted: Number(rec.jointProbAdjusted) || 0,
        expectedValue: Number(rec.expectedValue) || 0,
        kellyStake: Number(rec.kellyStake) || 0,
        correlationScore: Number(rec.correlationScore) || 0,
        varianceScore: Number(rec.varianceScore) || 0,
        timestamp: rec.timestamp || new Date().toISOString(),
        legs: (rec.legs || []).map((leg: any) => ({
            playerId: leg.playerId || "unknown",
            playerName: leg.playerName || "Unknown Player",
            team: leg.team || "N/A",
            opponent: leg.opponent || "N/A",
            statType: leg.statType || "Prop",
            line: Number(leg.line) || 0,
            prediction: leg.prediction || "Over",
            bookOdds: Number(leg.bookOdds) || -110,
            modelProb: Number(leg.modelProb) || 0.60,
            impliedProb: Number(leg.impliedProb) || 0.55,
            edge: Number(leg.edge) || 0,
            rationale: leg.rationale || "Analysis provided."
        }))
    }));
};

export const generateParlays = async (
  league: League,
  risk: RiskLevel,
  filters: string,
  statType: string = 'Any'
): Promise<ParlayRecommendation[]> => {
    const apiKey = process.env.API_KEY;
    const isPlayerSearch = filters && filters.length > 2;
    const isDailyTop3 = !filters || filters.length === 0;

    // Immediate fallback if no key is present (dev mode safety)
    if (!apiKey) {
        console.warn("No API Key. Returning mocks.");
        return isPlayerSearch ? [getMockPlayerProfile(filters)] : getMockParlays(league, statType);
    }

    const ai = new GoogleGenAI({ apiKey });
    const modelId = "gemini-2.5-flash";

    const prompt = `
      Act as an Elite Algorithmic Betting Engine.
      MODE: ${isPlayerSearch ? "SINGLE PLAYER DEEP DIVE PROFILE" : "DAILY TOP 3 (3-LEG PARLAYS)"}
      Context: 
      - League: ${league}
      - Focus: ${filters || "Daily System Picks"}
      - Strategy: ${risk}
      - Stat Preference: ${statType}

      CONSTRAINTS:
      ${isDailyTop3 ? `
      - Return exactly 3 parlays.
      - Each parlay has 3 legs.
      ${statType !== 'Any' ? `- CRITICAL: Ensure ALL legs (or majority) involve the statistic type: "${statType}".` : ''}
      ` : `
      - Generate a comprehensive scouting report for the player.
      - MUST include legs for: Points, Rebounds, Assists, 3PM, and PRA.
      - Provide a "prediction" (Over/Under) and "modelProb" (0.00-1.00) for EACH.
      `}

      OUTPUT JSON ONLY. Structure:
      {
        "recommendations": [
          {
            "type": "parlay" | "player_profile",
            "summary": "string",
            "legs": [
              {
                "playerName": "string",
                "team": "string",
                "opponent": "string",
                "statType": "string",
                "line": number,
                "prediction": "Over" | "Under",
                "bookOdds": number,
                "modelProb": number,
                "rationale": "string"
              }
            ]
          }
        ]
      }
    `;

    try {
        const response = await ai.models.generateContent({
            model: modelId,
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
            }
        });

        if (!response.text) throw new Error("No text returned from model");
        return parseResponse(response.text, isPlayerSearch);

    } catch (error: any) {
        // Broad detection for Quota, Rate Limits, or Overloaded Model
        const isQuotaError = 
            error.status === 429 || 
            error.status === 503 ||
            (error.message && (
                error.message.includes('429') || 
                error.message.includes('quota') || 
                error.message.includes('RESOURCE_EXHAUSTED') ||
                error.message.includes('rate limit')
            ));

        if (isQuotaError) {
            console.warn("API Quota Exceeded. Falling back to local simulation engine.");
            // Return high-quality mock data so the app doesn't break for the user
            if (isPlayerSearch) {
                return [getMockPlayerProfile(filters)];
            } else {
                return getMockParlays(league, statType);
            }
        }

        // If it's a different error, rethrow it to be handled by the UI
        throw error;
    }
};

