              <div className="text-2xl font-mono font-bold text-white flex items-center justify-end gap-2">
                  <span className="text-emerald-400">{bestLeg?.statType}</span>
                  <span className={bestLeg?.prediction === 'Over' ? 'text-emerald-400' : 'text-rose-400'}>
                    {bestLeg?.prediction === 'Over' ? 'O' : 'U'} {bestLeg?.line}
                  </span>
              </div>
          </div>
       </div>

       {/* Smart Stats Dashboard */}
       {bestLeg && (
       <div className="px-6 pb-6 relative z-10">
          <div className="bg-gray-900 border border-gray-800 rounded-lg overflow-hidden">

             {/* Tab Navigation */}
             <div className="flex border-b border-gray-800">
                <button 
                  onClick={() => setActiveTab('trends')}
