                             />
                             <ReferenceLine y={bestLeg.line} stroke="#fff" strokeDasharray="3 3" label={{ position: 'right', value: 'Line', fill: 'white', fontSize: 10 }} />
                             <ReferenceLine y={statsData.avg} stroke="#10b981" strokeOpacity={0.5} />
                             <Area type="monotone" dataKey="value" stroke="#10b981" fillOpacity={1} fill="url(#colorVal)" />
                          </AreaChart>
                       </ResponsiveContainer>
                    </div>
                ) : (
                    <div className="w-full overflow-x-auto">
                        <table className="w-full text-left text-sm">
                            <thead>
                                <tr className="border-b border-gray-800 text-gray-500 text-xs uppercase tracking-wider">
                                    <th className="pb-3 font-medium">Date</th>
                                    <th className="pb-3 font-medium">Opponent</th>
