export const PlayerProfileCard: React.FC<PlayerProfileCardProps> = ({ data }) => {
  const [activeTab, setActiveTab] = useState<'trends' | 'logs'>('trends');

  const sortedLegs = [...data.legs].sort((a, b) => (b.modelProb || 0) - (a.modelProb || 0));
  const bestLeg = sortedLegs[0];
  const playerLeg = bestLeg;
  const playerName = playerLeg?.playerName || "Unknown Player";
  const teamInfo = playerLeg ? `${playerLeg.team} vs ${playerLeg.opponent}` : "N/A";

  // --- Client-Side Simulation Logic for Charts ---
  // Since we don't have a real historical DB in this MVP, we simulate realistic logs 
  // based on the current line and variance to demonstrate the UI capabilities.
  const statsData = useMemo(() => {
    if (!bestLeg) return { logs: [], trend: [], avg: 0 };

    const line = bestLeg.line;
    const isOver = bestLeg.prediction === 'Over';

    // Simulate Season Average (usually slightly below line if Over, or above if Under)
    const avg = isOver ? line - (line * 0.05) : line + (line * 0.05);

    // Simulate Last 10 Games
    const trend = [];
    const logs = [];
    let wins = 0;

    for (let i = 1; i <= 10; i++) {
        // Random variance based on stat magnitude
        const variance = line * 0.3; // 30% swing
        const randomVal = (Math.random() - 0.5) * 2 * variance;
        // Bias towards the prediction
        const bias = isOver ? (line * 0.05) : -(line * 0.05);

        let val = Math.round(avg + randomVal + bias);
        if (val < 0) val = 0;

        const date = new Date();
        date.setDate(date.getDate() - (11 - i) * 2); // Every 2 days

        const hit = isOver ? val > line : val < line;
        if (hit) wins++;

        trend.push({
            game: `G${i}`,
            value: val,
            line: line,
            avg: avg
        });

        if (i > 5) { // Last 5 for logs
            logs.push({
                date: date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
                opponent: ['MIA', 'LAL', 'BOS', 'NYK', 'PHI'][i - 6],
                result: hit ? 'W' : 'L',
                value: val,
                line: line
            });
        }
    }
    return { logs: logs.reverse(), trend, avg };
  }, [bestLeg]);

  return (
    <div className="bg-gray-850 rounded-xl border border-gray-800 shadow-xl overflow-hidden mb-8 relative">
