             <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/5 to-transparent group-hover:via-white/10 transition-all"></div>
             <User size={40} className="text-gray-400" />
          </div>

          <div className="flex-1">
             <div className="flex items-center gap-2 mb-2">
                <span className="px-2 py-0.5 bg-blue-500/10 border border-blue-500/20 text-blue-400 text-[10px] rounded uppercase font-bold tracking-wider flex items-center gap-1">
                    <Activity size={10} /> Scouting Report
                </span>
             </div>
             <h2 className="text-3xl font-bold text-white tracking-tight mb-1">{playerName}</h2>
             <p className="text-gray-400 font-mono text-sm uppercase tracking-wider flex items-center gap-2">
                {teamInfo} <span className="text-gray-600">|</span> <span className="text-emerald-400">Active</span>
             </p>
          </div>

          <div className="text-right hidden sm:block bg-gray-900/80 backdrop-blur p-4 rounded-lg border border-gray-700/50 shadow-lg">
              <div className="text-[10px] text-gray-400 uppercase tracking-widest mb-1">Top Model Edge</div>
              <div className="text-2xl font-mono font-bold text-white flex items-center justify-end gap-2">
                  <span className="text-emerald-400">{bestLeg?.statType}</span>
                  <span className={bestLeg?.prediction === 'Over' ? 'text-emerald-400' : 'text-rose-400'}>
                    {bestLeg?.prediction === 'Over' ? 'O' : 'U'} {bestLeg?.line}
                  </span>
              </div>
          </div>
       </div>

       {/* Smart Stats Dashboard */}
       {bestLeg && (
       <div className="px-6 pb-6 relative z-10">
          <div className="bg-gray-900 border border-gray-800 rounded-lg overflow-hidden">

             {/* Tab Navigation */}
             <div className="flex border-b border-gray-800">
                <button 
                  onClick={() => setActiveTab('trends')}
                  className={`flex items-center gap-2 px-6 py-3 text-xs font-bold uppercase tracking-wider transition-colors ${activeTab === 'trends' ? 'bg-gray-800 text-emerald-400 border-b-2 border-emerald-500' : 'text-gray-500 hover:text-gray-300'}`}
                >
                    <History size={14} /> Trend Analysis
                </button>
                <button 
                  onClick={() => setActiveTab('logs')}
                  className={`flex items-center gap-2 px-6 py-3 text-xs font-bold uppercase tracking-wider transition-colors ${activeTab === 'logs' ? 'bg-gray-800 text-emerald-400 border-b-2 border-emerald-500' : 'text-gray-500 hover:text-gray-300'}`}
                >
                    <TableIcon size={14} /> Recent Game Logs
                </button>
             </div>

             <div className="p-6 bg-gray-900/50">
                {activeTab === 'trends' ? (
                    <div className="h-64 w-full">
                       <div className="flex justify-between items-center mb-4">
                          <h4 className="text-sm text-gray-300 font-bold flex items-center gap-2">
                             L10 Performance: {bestLeg.statType}
                          </h4>
                          <div className="flex items-center gap-4 text-xs font-mono">
                             <span className="flex items-center gap-1 text-gray-500">
                                <div className="w-3 h-1 bg-emerald-500/50"></div> Avg: {statsData.avg.toFixed(1)}
                             </span>
                             <span className="flex items-center gap-1 text-white">
                                <div className="w-3 h-0.5 bg-white border border-dashed"></div> Line: {bestLeg.line}
                             </span>
                          </div>
                       </div>
                       <ResponsiveContainer width="100%" height="100%">
                          <AreaChart data={statsData.trend}>
                             <defs>
                                <linearGradient id="colorVal" x1="0" y1="0" x2="0" y2="1">
                                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.3}/>
                                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                                </linearGradient>
                             </defs>
                             <CartesianGrid strokeDasharray="3 3" stroke="#374151" vertical={false} />
                             <XAxis dataKey="game" tick={{fill: '#6b7280', fontSize: 10}} axisLine={false} tickLine={false} />
                             <YAxis hide domain={['dataMin - 5', 'dataMax + 5']} />
                             <Tooltip 
                                contentStyle={{ backgroundColor: '#111827', borderColor: '#374151', fontSize: '12px' }}
                                itemStyle={{ color: '#e5e7eb' }}
                             />
                             <ReferenceLine y={bestLeg.line} stroke="#fff" strokeDasharray="3 3" label={{ position: 'right', value: 'Line', fill: 'white', fontSize: 10 }} />
                             <ReferenceLine y={statsData.avg} stroke="#10b981" strokeOpacity={0.5} />
                             <Area type="monotone" dataKey="value" stroke="#10b981" fillOpacity={1} fill="url(#colorVal)" />
                          </AreaChart>
                       </ResponsiveContainer>
                    </div>
                ) : (
                    <div className="w-full overflow-x-auto">
                        <table className="w-full text-left text-sm">
                            <thead>
                                <tr className="border-b border-gray-800 text-gray-500 text-xs uppercase tracking-wider">
                                    <th className="pb-3 font-medium">Date</th>
                                    <th className="pb-3 font-medium">Opponent</th>
                                    <th className="pb-3 font-medium text-right">Line</th>
                                    <th className="pb-3 font-medium text-right">Result</th>
                                    <th className="pb-3 font-medium text-right">Actual</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-800/50 font-mono">
                                {statsData.logs.map((log, i) => (
                                    <tr key={i} className="hover:bg-gray-800/50 transition-colors">
                                        <td className="py-3 text-gray-400">{log.date}</td>
                                        <td className="py-3 text-gray-300">@{log.opponent}</td>
