                                                <span className="text-rose-400 flex items-center justify-end gap-1"><XCircle size={12}/> Miss</span>
                                            )}
                                        </td>
                                        <td className="py-3 text-right font-bold text-white">{log.value}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
             </div>
          </div>
       </div>
       )}

       {/* Props Table Header */}
       <div className="bg-gray-950 border-y border-gray-800 px-4 py-3 flex items-center justify-between sticky top-0 z-20">
