          </div>
          <span className="text-[10px] text-gray-600 font-mono hidden sm:inline">PROBABILITY RANKED</span>
       </div>

       {/* Props List */}
       <div className="divide-y divide-gray-800">
          {bestLeg && (
             <div className="relative">
                 <div className="absolute left-0 top-0 bottom-0 w-1 bg-emerald-500"></div>
                 <div className="absolute right-4 top-2">
                    <span className="text-[9px] font-bold bg-emerald-500 text-gray-900 px-1.5 py-0.5 rounded uppercase tracking-wider flex items-center gap-1">
                        <Lock size={8} /> Top Value
                    </span>
                 </div>
                 <PropRow leg={bestLeg} isBest={true} />
             </div>
          )}
          {data.legs.slice(1).map((leg, i) => (
