       <div className="absolute top-0 w-full h-1 bg-gradient-to-r from-blue-500 via-emerald-500 to-purple-500 z-10"></div>

       <div className="relative z-10 p-6 flex flex-col sm:flex-row items-start sm:items-center gap-6">
          <div className="w-20 h-20 rounded-full bg-gray-800 border-4 border-gray-700 flex items-center justify-center shadow-2xl shrink-0 relative overflow-hidden group">
             <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/5 to-transparent group-hover:via-white/10 transition-all"></div>
             <User size={40} className="text-gray-400" />
          </div>

          <div className="flex-1">
             <div className="flex items-center gap-2 mb-2">
                <span className="px-2 py-0.5 bg-blue-500/10 border border-blue-500/20 text-blue-400 text-[10px] rounded uppercase font-bold tracking-wider flex items-center gap-1">
                    <Activity size={10} /> Scouting Report
                </span>
             </div>
             <h2 className="text-3xl font-bold text-white tracking-tight mb-1">{playerName}</h2>
             <p className="text-gray-400 font-mono text-sm uppercase tracking-wider flex items-center gap-2">
                {teamInfo} <span className="text-gray-600">|</span> <span className="text-emerald-400">Active</span>
             </p>
          </div>

          <div className="text-right hidden sm:block bg-gray-900/80 backdrop-blur p-4 rounded-lg border border-gray-700/50 shadow-lg">
              <div className="text-[10px] text-gray-400 uppercase tracking-widest mb-1">Top Model Edge</div>
              <div className="text-2xl font-mono font-bold text-white flex items-center justify-end gap-2">
                  <span className="text-emerald-400">{bestLeg?.statType}</span>
                  <span className={bestLeg?.prediction === 'Over' ? 'text-emerald-400' : 'text-rose-400'}>
                    {bestLeg?.prediction === 'Over' ? 'O' : 'U'} {bestLeg?.line}
                  </span>
              </div>
          </div>
       </div>

       {/* Season Averages Summary */}
       <div className="relative z-10 px-6 py-4 bg-gray-900/40 border-t border-b border-gray-800 grid grid-cols-4 gap-4">
            <SeasonStatBadge label="Season PPG" value={`${ptsLeg}`} subtext="Points" />
            <SeasonStatBadge label="Season RPG" value={`${rebLeg}`} subtext="Rebounds" />
            <SeasonStatBadge label="Season APG" value={`${astLeg}`} subtext="Assists" />
