// Helper to simulate "smart" math for offline mode
const calculateSmartEdge = (prob: number, odds: number) => {
    // implied prob of -110 is ~52.38%
    const decimalOdds = odds > 0 ? (odds / 100) + 1 : (100 / Math.abs(odds)) + 1;
    const implied = 1 / decimalOdds;
    const edge = (prob - implied) * 100;
    return { implied, edge };
};

const generateMockLeg = (player: string, type: string, line: number, pred: 'Over' | 'Under', prob: number, hitRate: string): BetLeg => {
    const { implied, edge } = calculateSmartEdge(prob, -110);

    // Generate context-aware rationale parts
    const rank = Math.floor(Math.random() * 10) + 20; // Rank 20-30 (bad defense)
    const pace = (Math.random() * 2 + 100).toFixed(1);

    return {
        playerId: player.toLowerCase().replace(/\s/g, '-'),
        playerName: player,
        team: "TB", 
        opponent: "MIA",
        statType: type,
        line: line,
        prediction: pred,
        bookOdds: -110,
        modelProb: prob,
        impliedProb: parseFloat(implied.toFixed(3)),
        edge: parseFloat(edge.toFixed(2)),
        rationale: `Hit in ${hitRate} L10. Opponent ranks ${rank}th vs ${type}. Pace: ${pace} (Fast). High usage correlation.`
    };
};

const getMockPlayerProfile = (query: string): ParlayRecommendation => {
