import { GoogleGenAI } from "@google/genai";
import { League, RiskLevel, ParlayRecommendation, BetLeg } from "../types";

// --- Mock Data Generators (Fallback for 429/Quota Errors) ---

const calculateSmartEdge = (prob: number, odds: number) => {
    // implied prob of -110 is ~52.38%
    const decimalOdds = odds > 0 ? (odds / 100) + 1 : (100 / Math.abs(odds)) + 1;
    const implied = 1 / decimalOdds;
    const edge = (prob - implied) * 100;
    return { implied, edge };
};

const generateMockPropLeg = (player: string, stat: string, line: number, pred: 'Over' | 'Under', prob: number): BetLeg => {
    const { implied, edge } = calculateSmartEdge(prob, -110);
    return {
        playerId: player.toLowerCase().replace(/\s/g, '-'),
        playerName: player,
        team: "MIN", 
        opponent: "LAL",
        statType: stat,
        line: line,
        prediction: pred,
        bookOdds: -110,
        modelProb: prob,
        impliedProb: parseFloat(implied.toFixed(3)),
        edge: parseFloat(edge.toFixed(2)),
        rationale: `Model projects ${pred === 'Over' ? (line * 1.15).toFixed(1) : (line * 0.85).toFixed(1)} ${stat} based on L10 usage rate.`,
        injuryStatus: "Active"
    };
};

const getMockPlayerProfile = (name: string = "Anthony Edwards"): ParlayRecommendation => {
    return {
        type: 'player_profile',
        id: `mock-profile-${name}-${Date.now()}`,
        summary: `[OFFLINE MODE] Displaying simulated market analysis for ${name}. High confidence in scoring props due to matchup pace.`,
        totalOdds: 0,
        jointProbAdjusted: 0,
        expectedValue: 12.5,
        kellyStake: 0,
        correlationScore: 0,
        varianceScore: 3.5,
        timestamp: new Date().toISOString(),
        legs: [
            generateMockPropLeg(name, "Points", 27.5, "Over", 0.62),
            generateMockPropLeg(name, "Rebounds", 6.5, "Under", 0.58),
            generateMockPropLeg(name, "Assists", 5.5, "Over", 0.54),
            generateMockPropLeg(name, "3-Pointers", 3.5, "Over", 0.60),
            generateMockPropLeg(name, "PRA", 38.5, "Over", 0.65),
        ]
    };
};

// Returns a list of trending players when no search is provided
const getMockTrendingPlayers = (league: League): ParlayRecommendation[] => {
    const nbaPlayers = ["Luka Doncic", "Giannis Antetokounmpo", "Jayson Tatum"];
    const nflPlayers = ["Patrick Mahomes", "Lamar Jackson", "Christian McCaffrey"];
    const mlbPlayers = ["Shohei Ohtani", "Aaron Judge", "Mookie Betts"];

    let pool = nbaPlayers;
    if (league === League.NFL) pool = nflPlayers;
    if (league === League.MLB) pool = mlbPlayers;

    return pool.map(p => getMockPlayerProfile(p));
};

// --- Main Service Logic ---

const cleanJsonText = (text: string): string => {
    let cleaned = text.replace(/```json/g, '').replace(/```/g, '');
    const startIndex = cleaned.indexOf('{');
    const endIndex = cleaned.lastIndexOf('}');

    if (startIndex === -1 || endIndex === -1) {
        throw new Error("AI returned unstructured text.");
    }

    cleaned = cleaned.substring(startIndex, endIndex + 1);
    cleaned = cleaned.replace(/:\s*\+(\d+)/g, ': $1');
    return cleaned;
};

const parseResponse = (text: string): ParlayRecommendation[] => {
    try {
        const jsonString = cleanJsonText(text);
        const parsed = JSON.parse(jsonString);

        return (parsed.recommendations || []).map((rec: any, index: number) => {
            const mappedLegs = (rec.legs || []).map((leg: any) => ({
                playerId: leg.playerId || "unknown",
                playerName: leg.playerName || "Unknown Player",
                team: leg.team || "N/A",
                opponent: leg.opponent || "N/A",
                statType: leg.statType || "Prop",
                line: Number(leg.line) || 0,
                prediction: leg.prediction || "Over",
                bookOdds: Number(leg.bookOdds) || -110,
                modelProb: Number(leg.modelProb) || 0.60,
                impliedProb: Number(leg.impliedProb) || 0.55,
                edge: Number(leg.edge) || 0,
                rationale: leg.rationale || "Analysis provided.",
                injuryStatus: leg.injuryStatus || "Active"
            }));

            // FAILSAFE: Filter out players that are explicitly marked as Out/Doubtful by the LLM
            const validLegs = mappedLegs.filter((leg: any) => {
                const status = (leg.injuryStatus || "").toLowerCase();
                const isOut = status.includes('out') || status.includes('doubtful') || status.includes('injured') || status.includes('ir');
                if (isOut) {
                    console.warn(`Filtered out injured player: ${leg.playerName} (${leg.injuryStatus})`);
                }
                return !isOut;
            });

            return {
                type: 'player_profile', // FORCE player_profile type
                id: rec.id || `rec-${index}-${Date.now()}`,
                summary: rec.summary || "Analysis generated.",
                totalOdds: Number(rec.totalOdds) || 0,
                jointProbAdjusted: Number(rec.jointProbAdjusted) || 0,
                expectedValue: Number(rec.expectedValue) || 0,
                kellyStake: Number(rec.kellyStake) || 0,
                correlationScore: Number(rec.correlationScore) || 0,
                varianceScore: Number(rec.varianceScore) || 0,
                timestamp: rec.timestamp || new Date().toISOString(),
                legs: validLegs
            };
        })
        .filter((rec: any) => rec.legs.length > 0);

    } catch (e) {
        console.warn("JSON Parse Failed, falling back to mock. Raw Text:", text);
        throw e; 
    }
};

export const generateParlays = async (
  league: League,
  risk: RiskLevel,
  filters: string,
  statType: string = 'Any',
  advancedMetric: string = 'Standard'
): Promise<ParlayRecommendation[]> => {
    const apiKey = process.env.API_KEY;
    const hasSearchTerm = filters && filters.length > 2;

    if (!apiKey) {
        console.warn("No API Key. Returning mocks.");
        return hasSearchTerm ? [getMockPlayerProfile(filters)] : getMockTrendingPlayers(league);
    }

    try {
        const ai = new GoogleGenAI({ apiKey });
        const modelId = "gemini-2.5-flash";

        // Prompt adjusted for Single Player Prop Search Engine
        const prompt = `
          Act as a Player Prop Search Engine & Betting Model.

          TASK:
          Generate a detailed 'player_profile' JSON for the requested player(s).

          INPUTS:
          - League: ${league}
          - Search Query: ${hasSearchTerm ? `"${filters}"` : "None (Select 3 Trending/Star Players for Today)"}
          - Risk Profile: ${risk}
          - Metric Priority: ${advancedMetric}

          INJURY & ROSTER CHECK (MANDATORY):
          1. LIVE SEARCH: Check injury status for every player AND their key teammates/opponents.
          2. EXCLUDE: Players listed as OUT, DOUBTFUL, or IR.
          3. VERIFY TEAM: Check for recent trades (e.g. Siakam to IND). Use current team abbreviation.

          INJURY CORRELATION ADJUSTMENT (CRITICAL):
          - IF a key teammate is OUT, you MUST adjust the target player's projection based on "Usage Absorption".
            (e.g., If Embiid is OUT -> Maxey usage spikes -> Boost Points/Assists probability significantly).
          - IF a primary defender on the opposing team is OUT, boost the target player's efficiency.
          - Explicitly mention these correlation factors in the 'rationale' field if they apply (e.g., "Usage bump w/ [Teammate] OUT").

          OUTPUT REQUIREMENT:
          - Return a JSON object with a "recommendations" array.
          - Each item in "recommendations" MUST be a Player Profile containing multiple prop markets for THAT SPECIFIC PLAYER.
          - DO NOT generate parlays combining different players.
          - If NO search query is provided, pick 3 separate star players playing today and generate a profile for each.

          PROFILE CONTENT (legs array):
          - For each player, generate 5-6 different prop markets (e.g., Points, Rebounds, Assists, 3PM, P+R+A).
          - Compare lines from DraftKings, FanDuel, PrizePicks.
          - Calculate 'modelProb' and 'edge'.

          OUTPUT FORMAT (JSON ONLY):
          {
            "recommendations": [
              {
                "type": "player_profile",
                "summary": "Analysis of [Player Name] vs [Opponent]...",
                "expectedValue": number, // Overall rating 0-100
                "legs": [
                  {
                    "playerName": "string",
                    "team": "string",
                    "opponent": "string",
                    "statType": "string (e.g. Points, Rebounds)",
                    "line": number,
                    "prediction": "Over" | "Under",
                    "bookOdds": number,
                    "modelProb": number,
                    "impliedProb": number,
                    "edge": number,
                    "rationale": "string",
                    "injuryStatus": "Active" | "Questionable" | "GTD"
                  }
                ]
              }
            ]
          }
        `;

        const response = await ai.models.generateContent({
            model: modelId,
            contents: prompt,
            config: {
                tools: [{ googleSearch: {} }],
                temperature: 0.4, 
            }
        });

        if (!response.text) throw new Error("No text returned from model");
        return parseResponse(response.text);

    } catch (error: any) {
        console.warn("Gemini API Unavailable or Parse Failed. Switching to Simulation.", error.message);
        if (hasSearchTerm && filters.length > 2) {
             return [getMockPlayerProfile(filters)];
        } else {
             return getMockTrendingPlayers(league);
        }
    }
};

