    const regex = /((?:Hit in \d+\/\d+)|(?:\d+\/\d+)|(?:L\d+)|(?:Rank #?\d+)|(?:\d+th)|(?:vs \w+)|(?:Pace)|(?:Usage)|(?:Def))/gi;
    const parts = text.split(regex);

    return (
        <span className="flex-1">
