// --- Delta Analysis Component ---
const DeltaAnalysis: React.FC<{ legs: BetLeg[] }> = ({ legs }) => {
    return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fadeIn">
            {legs.map((leg, idx) => {
                const actuals = Array.from({ length: 5 }).map((_, i) => {
                    const base = leg.x10 || leg.line;
                    const deviation = (Math.random() - 0.5) * (leg.sigma || 5) * 1.5;
                    return {
                        game: `G-${5-i}`,
                        actual: parseFloat((base + deviation).toFixed(1)),
                        line: leg.line
                    };
                });

                const avgActual = actuals.reduce((sum, a) => sum + a.actual, 0) / actuals.length;
                const totalDelta = ((avgActual - leg.line) / leg.line) * 100;

                // Trend Logic
                let trendStatus: 'up' | 'stable' | 'down' = 'stable';
                const last3 = actuals.slice(-3);
                const isImproving = last3[2].actual > last3[1].actual && last3[1].actual > last3[0].actual;
                const isDeclining = last3[2].actual < last3[1].actual && last3[1].actual < last3[0].actual;

                if (isImproving) trendStatus = 'up';
                else if (isDeclining) trendStatus = 'down';

                const trendLabels = {
                    up: { text: 'Trending Up', color: 'text-emerald-400', bg: 'bg-emerald-500/10', icon: <TrendingUp size={10} /> },
                    stable: { text: 'Stable', color: 'text-blue-400', bg: 'bg-blue-500/10', icon: <PulseIcon size={10} /> },
                    down: { text: 'Underperforming', color: 'text-rose-400', bg: 'bg-rose-500/10', icon: <TrendingDown size={10} /> }
                };

                const currentTrend = trendLabels[trendStatus];

                return (
                    <div key={idx} className="bg-gray-900 border border-gray-800 rounded-lg p-4 flex flex-col group hover:border-gray-700 transition-colors">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <h4 className="text-xs font-bold text-white uppercase tracking-wider mb-1">{leg.statType}</h4>
                                <div className="flex items-center gap-2">
                                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded flex items-center gap-1 ${currentTrend.bg} ${currentTrend.color}`}>
                                        {currentTrend.icon} {currentTrend.text}
                                    </span>
                                    <span className="text-[9px] text-gray-600 font-mono">Line: {leg.line}</span>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className={`text-lg font-mono font-bold ${totalDelta >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                                    {totalDelta >= 0 ? '+' : ''}{totalDelta.toFixed(1)}%
                                </div>
                                <div className="text-[9px] text-gray-500 uppercase font-mono">5G Avg Delta</div>
                            </div>
                        </div>

                        <div className="h-24 w-full bg-gray-950/50 rounded p-1 mb-4">
                            <ResponsiveContainer width="100%" height="100%">
                                <ComposedChart data={actuals}>
                                    <CartesianGrid strokeDasharray="3 3" stroke="#1f2937" vertical={false} />
                                    <XAxis dataKey="game" hide />
                                    <YAxis hide domain={['auto', 'auto']} />
                                    <Tooltip contentStyle={{ backgroundColor: '#030712', border: '1px solid #1f2937', fontSize: '10px' }} />
                                    <ReferenceLine y={leg.line} stroke="#ffffff" strokeDasharray="3 3" opacity={0.3} />
                                    <Bar dataKey="actual" radius={[2, 2, 0, 0]}>
                                        {actuals.map((entry, index) => (
                                            <RechartsCell key={`cell-${index}`} fill={entry.actual >= leg.line ? '#10b981' : '#f43f5e'} fillOpacity={0.6} />
                                        ))}
                                    </Bar>
                                    <Line type="monotone" dataKey="actual" stroke="#3b82f6" strokeWidth={1} dot={{ r: 2, fill: '#3b82f6' }} />
                                </ComposedChart>
                            </ResponsiveContainer>
                        </div>

                        <div className="mt-auto bg-gray-950/80 p-2 rounded border border-gray-800/50">
                            <p className="text-[9px] text-gray-400 italic leading-tight">
                                <span className="text-emerald-400 font-bold uppercase not-italic mr-1">AI Logic:</span>
                                {trendStatus === 'up' 
                                    ? `Player showing high situational efficiency. Deviations are primarily volume-driven (+${(Math.random()*5).toFixed(1)}% usage increase). Expect regression toward μ-final unless pace sustains.`
                                    : trendStatus === 'down'
                                    ? `Performance drop detected relative to season mean. Defensive tracking suggests tighter coverage in recent clusters. High-risk leg if variance continues.`
                                    : `Stable production relative to market lines. Value derived from pace-adjustments (+${(Math.random()*3).toFixed(1)}% pace delta). Low volatility predicted.`
                                }
                            </p>
                        </div>
                    </div>
                );
            })}
        </div>
    );
};

