const PropRow: React.FC<{ leg: BetLeg; isBest?: boolean }> = ({ leg, isBest }) => {
  const [showMath, setShowMath] = useState(false);

  // Local state for manual adjustments
  const [localLine, setLocalLine] = useState(leg.line.toString());
  const [localOdds, setLocalOdds] = useState(leg.bookOdds.toString());
  const [calcLeg, setCalcLeg] = useState(leg);
  const [isRecalculating, setIsRecalculating] = useState(false);

  const m = useMemo(() => calculateEngineMetrics(calcLeg), [calcLeg]);

  const handleRecalculate = () => {
    setIsRecalculating(true);
    // Simulate brief processing
    setTimeout(() => {
        setCalcLeg({
            ...leg,
            line: parseFloat(localLine) || 0,
            bookOdds: parseFloat(localOdds) || -110
        });
        setIsRecalculating(false);
    }, 400);
  };

  const hitRateValue = m.pModel * 100;
  const probabilityColor = hitRateValue >= 65 ? 'text-emerald-400' : hitRateValue >= 55 ? 'text-yellow-400' : 'text-gray-400';

  // League average comparison logic
  const leagueAvg = leg.leagueAvg || (leg.line * 0.8); // fallback
  const diffFromAvg = ((m.muFinal - leagueAvg) / leagueAvg) * 100;

  const hasAdjusted = parseFloat(localLine) !== leg.line || parseFloat(localOdds) !== leg.bookOdds;

  return (
    <div className={`p-4 border-b border-gray-800 transition-colors ${isBest ? 'bg-emerald-950/10' : 'bg-gray-900'}`}>
        <div className="grid grid-cols-12 gap-4 items-center">
            <div className="col-span-12 lg:col-span-3">
                <div className="flex items-center gap-2">
                    <div className="text-sm font-bold text-gray-100">{leg.statType}</div>
                    <span className="text-[9px] bg-gray-800 text-emerald-400 px-1 rounded font-mono border border-emerald-500/20">
                        L10: {leg.recentHitRate || 'N/A'}
                    </span>
                </div>
                <div className="flex items-center gap-2 mt-0.5">
                    <div className="text-[9px] text-gray-600 font-mono">μ Final: {m.muFinal.toFixed(1)}</div>
                    <div className={`text-[8px] font-bold px-1 rounded-sm ${diffFromAvg >= 0 ? 'bg-emerald-500/10 text-emerald-400' : 'bg-rose-500/10 text-rose-400'}`}>
                        {diffFromAvg >= 0 ? '+' : ''}{diffFromAvg.toFixed(0)}% VS L_AVG
                    </div>
                </div>
            </div>

            <div className="col-span-4 lg:col-span-2">
                <div className="flex flex-col items-center">
                    <div className="flex items-center gap-1">
                        <span className={`text-xs font-mono font-bold ${leg.prediction === 'Over' ? 'text-emerald-400' : 'text-rose-400'}`}>
                            {leg.prediction === 'Over' ? 'O' : 'U'}
                        </span>
                        <input 
                            type="number" 
                            step="0.5"
                            value={localLine}
                            onChange={(e) => setLocalLine(e.target.value)}
                            className="w-14 bg-gray-950 border border-gray-800 text-white text-xs font-mono font-bold px-1 py-0.5 rounded focus:border-emerald-500 outline-none hover:border-gray-700 transition-colors"
                        />
                    </div>
                    <div className="text-[8px] text-gray-500 uppercase font-mono mt-1">Manual Line</div>
                </div>
            </div>

            <div className="col-span-4 lg:col-span-1">
                <div className="flex flex-col items-center">
                    <input 
                        type="number" 
                        step="1"
                        value={localOdds}
                        onChange={(e) => setLocalOdds(e.target.value)}
                        className="w-16 bg-gray-950 border border-gray-800 text-gray-300 text-xs font-mono px-1 py-0.5 rounded focus:border-emerald-500 outline-none hover:border-gray-700 transition-colors"
                    />
                    <div className="text-[8px] text-gray-500 uppercase font-mono mt-1">Odds</div>
                </div>
            </div>

            <div className="col-span-4 lg:col-span-1 text-center">
                <div className={`text-base font-mono font-bold ${probabilityColor} ${isRecalculating ? 'animate-pulse opacity-50' : ''}`}>
                    {hitRateValue.toFixed(0)}%
                </div>
                <div className="text-[9px] text-gray-500 uppercase font-mono">Win Prob</div>
            </div>

            <div className="hidden lg:block lg:col-span-3">
