                    </div>
                    <span className={`text-[8px] px-1 rounded font-mono border transition-colors ${isActive ? 'bg-emerald-500 text-gray-950 border-emerald-400' : 'bg-gray-800 text-emerald-400 border-emerald-500/20'}`}>
