                            : 'bg-rose-500/20 border-rose-500 text-rose-400 shadow-[0_0_10px_rgba(244,63,94,0.3)]'
                        }`}
                        title="Toggle Over/Under"
                    >
                        {localPrediction === 'Over' ? 'O' : 'U'}
                    </button>
                    <input 
