                    title="Math Breakdown"
                >
                    <BrainCircuit size={14} />
                </button>
            </div>
        </div>

        {showMarket && <div onClick={e => e.stopPropagation()}><MarketComparison leg={calcLeg} /></div>}
        {showMath && <div onClick={e => e.stopPropagation()}><EngineBreakdown leg={calcLeg} /></div>}
    </div>
