                                : 'bg-rose-500/10 border-rose-500/20 text-rose-500 group-hover:bg-rose-500/20'
                              }`}>
                                  <div className="text-[8px] font-bold font-mono text-center leading-tight mb-1">{win.date}</div>
                                  {win.outcome === 'WIN' ? <CheckCircle2 size={18} /> : <XCircle size={18} />}
                              </div>
                              <div>
                                 <div className="flex items-center gap-2 mb-0.5">
                                    <div className="text-sm font-bold text-white">
                                        {win.player} <span className="text-gray-500 font-normal ml-1">vs {win.opponent}</span>
                                    </div>
                                    {win.type === 'parlay' && (
                                        <span className="text-[8px] px-1.5 rounded-full bg-blue-500/20 border border-blue-500/30 text-blue-400 font-bold uppercase tracking-widest flex items-center gap-1">
                                            <GitMerge size={8} /> PARLAY SUCCESS
                                        </span>
                                    )}
                                 </div>
                                 <div className="text-xs text-gray-500 font-mono">
                                    {win.type === 'parlay' ? <span className="text-blue-400 font-bold">{win.label}: </span> : ''}
                                    {win.prop} • <span className="text-gray-400 italic">Actual: </span>
                                    <span className={win.outcome === 'WIN' ? 'text-emerald-400 font-bold' : 'text-rose-400 font-bold'}>
                                      {win.result}
                                    </span>
                                 </div>
                              </div>
                           </div>
                           <div className="flex items-center gap-6 text-right ml-16 sm:ml-0">
                              <div className="hidden lg:block">
                                 <div className="text-[9px] text-gray-600 uppercase font-mono tracking-widest">Grounded On</div>
                                 <div className="text-[10px] text-gray-400 font-mono">{win.date}</div>
                              </div>
                              <div>
                                 <div className={`text-xs font-bold font-mono ${win.outcome === 'WIN' ? 'text-emerald-400' : 'text-rose-400'}`}>
                                    {win.odds}
                                 </div>
                                 <div className="text-[9px] text-gray-600 uppercase font-mono tracking-tighter">Settled Odds</div>
                              </div>
                           </div>
                        </div>
                      ))
                  ) : (
                    <div className="flex flex-col items-center justify-center py-24 text-gray-700">
                        <History size={48} className="mb-4 opacity-10" />
                        <p className="text-xs uppercase tracking-[0.3em] font-mono text-gray-600">Awaiting Live Settlement Feed for {historyLeague}</p>
                        <p className="text-[10px] font-mono mt-2 italic text-gray-800">Grounding active... check back after daily tip-offs.</p>
                    </div>
                  )}
               </div>
               <div className="px-6 py-4 bg-gray-950/30 border-t border-gray-800 flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                        <span className="text-[9px] text-gray-500 font-mono uppercase tracking-widest">Real-Time Outcome Decoder Active</span>
                    </div>
                    <p className="text-[9px] text-gray-700 italic font-mono uppercase tracking-tighter">
