import React, { useState, useEffect, useMemo } from 'react';
import './App.css';
import LandingPage from './components/LandingPage';
import SignUpPage from './components/SignUpPage';
import LoginPage from './components/LoginPage';
import AccessCodePage from './components/AccessCodePage';
import AboutPage from './components/AboutPage';
import { fetchTrendingPicks, fetchGroundedOutcomes } from './api';
import { HistoryIcon, CheckCircle2, XCircle, ListIcon } from './components/Icons'; // Corrected import
import { AppTab, ViewState } from './types';
import { generateParlays } from './parlay_logic';
import { useLocalStorage } from './hooks/useLocalStorage';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>('landing');
  const [formData, setFormData] = useState({ accessCode: '', username: '', password: '', email: '' });
  const [trendingPicks, setTrendingPicks] = useState<any[]>([]); // Assuming an array of any type
  const [groundedHistory, setGroundedHistory] = useState<any[]>([]); // Assuming an array of any type
  const [isLoading, setIsLoading] = useState(true);
  const [historyLoading, setHistoryLoading] = useState(true);
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [builderSearch, setBuilderSearch] = useState('');
  const [builderResults, setBuilderResults] = useState<any[]>([]); // Array of any types
  const [builderLegs, setBuilderLegs] = useState<any[]>([]); // Array of any types
  const [recommendations, setRecommendations] = useState<any[]>([]);
  const [recommendationsLoading, setRecommendationsLoading] = useState(false);
  const [recommendationsError, setRecommendationsError] = useState<string | null>(null);

  const [activeTab, setActiveTab] = useState<AppTab>('parlay'); // Default tab

  const [isSidebarOpen, setIsSidebarOpen] = useState(false); // Sidebar state
  const [useLocalData, setUseLocalData] = useLocalStorage('useLocalData', false);


  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      setError(null);
      try {
        const trendingData = await fetchTrendingPicks();
