// --- Shared Rationale Helpers ---
const getDefinition = (text: string) => {
    const lower = text.toLowerCase();
    if (lower.includes('bayesian')) return "Bayesian Inference: A statistical method that updates the probability of a hypothesis as more evidence (recent player form) becomes available.";
    if (lower.includes('regression')) return "Regression to Mean: The statistical tendency for extreme performances (hot/cold streaks) to eventually return to the player's long-term average.";
    if (lower.includes('edge')) return "Model Edge: The difference between our calculated probability and the bookmaker's implied probability.";
    if (lower.includes('z-score')) return "Z-Score: Measures how many standard deviations the betting line is from the projected mean (μ).";
    if (lower.includes('sigma') || lower.includes('deviation')) return "Standard Deviation (σ): Quantifies volatility; higher values indicate higher variance in player performance.";
    if (lower.includes('pace')) return "Pace Adjustment: Correcting projections based on the expected number of possessions in a specific matchup.";
    if (lower.includes('usage')) return "Usage Rate: The percentage of team plays a player is involved in while on the court/field.";
    return "Quant Insight: High-confidence projection derived from regression models and historical situational variance analysis.";
};

const HighlightedRationale: React.FC<{ text: string }> = ({ text }) => {
    if (!text) return null;
    const regex = /((?:DEF: #?\d+)|(?:PACE: [+-]?\d+(?:\.\d+)?%)|(?:HIT: \d+\/\d+)|(?:SITUATIONAL: [^,.]+)|(?:L\d+)|(?:Rank #?\d+)|(?:\d+th)|(?:vs \w+)|(?:Pace)|(?:Usage)|(?:Def))/gi;
    const parts = text.split(regex);
    return (
        <span>
            {parts.map((part, i) => {
                if (part.match(regex)) {
                    let colorClass = 'text-gray-200 bg-gray-800/50';
                    if (part.toUpperCase().startsWith('DEF:')) colorClass = 'text-orange-400 bg-orange-400/10 border-orange-400/20';
                    if (part.toUpperCase().startsWith('PACE:')) colorClass = 'text-blue-400 bg-blue-400/10 border-blue-400/20';
                    if (part.toUpperCase().startsWith('HIT:')) colorClass = 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20';
                    if (part.toUpperCase().startsWith('SITUATIONAL:')) colorClass = 'text-purple-400 bg-purple-400/10 border-purple-400/20';

                    return (
                        <span 
                          key={i} 
                          className={`${colorClass} font-bold font-mono text-[9px] px-1.5 py-0.5 rounded border mx-0.5 inline-flex items-center gap-1 transition-all hover:scale-105`}
                        >
                          {part}
                        </span>
                    );
                }
                return <span key={i} className="text-gray-400">{part}</span>;
            })}
        </span>
    );
};

// --- Delta Analysis Component ---
const PerformanceDeltaAnalysis: React.FC<{ leg: BetLeg }> = ({ leg }) => {
    const last5 = useMemo(() => (leg.recentGames || []).slice(0, 5).reverse(), [leg.recentGames]);

    const trendAnalysis = useMemo(() => {
        if (last5.length < 2) return { status: 'STABLE', color: 'text-blue-400', bg: 'bg-blue-500/10', summary: "Insufficient game logs for variance trend detection." };

        const actuals = last5.map(g => g.value);
        const hits = last5.filter(g => g.value >= leg.line).length;
        const avgActual = actuals.reduce((a, b) => a + b, 0) / actuals.length;
        const deviation = ((avgActual - leg.line) / leg.line) * 100;

        // Simple slope check
        const firstHalf = actuals.slice(0, Math.ceil(actuals.length / 2));
        const secondHalf = actuals.slice(Math.ceil(actuals.length / 2));
        const avg1 = firstHalf.reduce((a, b) => a + b, 0) / firstHalf.length;
        const avg2 = secondHalf.reduce((a, b) => a + b, 0) / secondHalf.length;

        if (avg2 > avg1 * 1.1 || hits >= 4) {
            return { 
                status: 'TRENDING UP', 
                color: 'text-emerald-400', 
                bg: 'bg-emerald-500/10',
                summary: `Player is outperforming the ${leg.line} market line by ${deviation.toFixed(1)}% over the L5. High upward momentum detected.` 
            };
        } else if (avg2 < avg1 * 0.9 || hits <= 1) {
            return { 
                status: 'UNDERPERFORMING', 
                color: 'text-rose-400', 
                bg: 'bg-rose-500/10',
                summary: `Significant cold streak detected. Performance is averaging ${Math.abs(deviation).toFixed(1)}% below current market projections.` 
            };
        } else {
            return { 
                status: 'STABLE', 
                color: 'text-blue-400', 
                bg: 'bg-blue-500/10',
                summary: `Performance is hovering within ±${Math.abs(deviation).toFixed(1)}% of the market line. High predictability, low volatility environment.` 
            };
        }
    }, [last5, leg.line]);

    return (
        <div className="space-y-6 animate-fadeIn">
            {/* Header / Summary */}
            <div className={`p-4 rounded-xl border flex flex-col md:flex-row items-center gap-4 ${trendAnalysis.bg} border-gray-800/50`}>
                <div className={`px-3 py-1.5 rounded-lg border border-current font-bold font-mono text-xs ${trendAnalysis.color}`}>
                    {trendAnalysis.status}
                </div>
                <div className="flex-1 text-xs text-gray-300 leading-relaxed font-medium italic">
                    <span className="text-gray-500 not-italic mr-2">QUANT SUMMARY:</span>
                    "{trendAnalysis.summary}"
                </div>
            </div>

            {/* Delta Grid */}
            <div className="grid grid-cols-1 md:grid-cols-5 gap-3">
                {last5.map((game, idx) => {
                    const diff = game.value - leg.line;
                    const diffPct = (diff / leg.line) * 100;
                    const isHit = game.value >= leg.line;

                    return (
                        <div key={idx} className="bg-gray-900 border border-gray-800 rounded-xl p-3 flex flex-col items-center group hover:border-gray-700 transition-all">
                            <div className="text-[8px] text-gray-600 font-mono uppercase mb-2">{game.date}</div>
                            <div className="text-xl font-mono font-bold text-white mb-1">{game.value}</div>
                            <div className={`text-[10px] font-bold font-mono ${isHit ? 'text-emerald-400' : 'text-rose-400'}`}>
                                {isHit ? '+' : ''}{diff.toFixed(1)}
                            </div>
                            <div className="w-full h-1 bg-gray-800 rounded-full mt-3 overflow-hidden">
                                <div 
                                    className={`h-full transition-all duration-500 ${isHit ? 'bg-emerald-500' : 'bg-rose-500'}`}
                                    style={{ width: `${Math.min(100, (game.value / (leg.line * 1.5)) * 100)}%` }}
                                ></div>
                            </div>
                            <div className="text-[8px] text-gray-500 font-mono mt-2 uppercase tracking-tighter">vs {leg.line} Line</div>
                        </div>
                    );
                })}
            </div>

            {/* Comparative Chart */}
            <div className="bg-gray-950 border border-gray-800 rounded-xl p-4 h-48">
                <div className="flex justify-between items-center mb-4">
                    <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest flex items-center gap-2">
                        {/* Changed BarChart to BarChart3 to match Icons export */}
                        <BarChart3 size={14} /> Deviation Waveform (L5)
                    </span>
                    <div className="flex gap-4 text-[8px] font-mono">
                         <span className="flex items-center gap-1"><div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div> Actual</span>
                         <span className="flex items-center gap-1 border-gray-800 border-l pl-2"><div className="w-1.5 h-1.5 rounded-full bg-white opacity-20"></div> Projection</span>
                    </div>
                </div>
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={last5}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#1f2937" vertical={false} />
                        <XAxis dataKey="date" hide />
                        <YAxis hide domain={['auto', 'auto']} />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#030712', border: '1px solid #1f2937', fontSize: '10px' }}
                            itemStyle={{ color: '#10b981' }}
                        />
                        <ReferenceLine y={leg.line} stroke="#ffffff" strokeDasharray="5 5" opacity={0.3} />
                        <Area 
                            type="monotone" 
