import { useState, useEffect, useMemo } from 'react';
import { generateParlays, fetchTrendingPicks, fetchGroundedOutcomes } from './services/geminiService';
import { League, RiskLevel, UserInputState, ParlayRecommendation, BetLeg } from './types';
import { InputForm } from './components/InputForm';
import { PlayerProfileCard } from './components/PlayerProfileCard';
import { LoadingScreen } from './components/LoadingScreen';
import { LandingPage } from './components/LandingPage';
import { SignUpPage } from './components/SignUpPage'; 
import { LoginPage } from './components/LoginPage';
import { AboutPage } from './components/AboutPage';
import { AccessCodePage } from './components/AccessCodePage';
import { calculateEngineMetrics } from './services/projectionEngine';
import { 
  BarChart3, ShieldAlert, Home, Zap, User, RefreshCw, 
  Target, TrendingUp, Trophy, HistoryIcon, CheckCircle2, XCircle, ListIcon, Clock, Calendar, GitMerge, Timer,
  Search, Plus, Trash2, Cpu, ArrowRight, BrainCircuit, X, Settings2
} from './components/Icons';

type ViewState = 'landing' | 'signup' | 'login' | 'app' | 'about' | 'access';
type AppTab = 'search' | 'parlays' | 'history';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>('landing');
  const [activeTab, setActiveTab] = useState<AppTab>('search');
  const [historyLeague, setHistoryLeague] = useState<League>(League.NBA);
  const [constructorLeague, setConstructorLeague] = useState<League>(League.NBA);
  const [isLoading, setIsLoading] = useState(false);
  const [isHistoryLoading, setIsHistoryLoading] = useState(false);

  const [recommendations, setRecommendations] = useState<ParlayRecommendation[]>([]);
  const [builderSearch, setBuilderSearch] = useState('');
  const [builderResults, setBuilderResults] = useState<BetLeg[]>([]);
  const [builderLegs, setBuilderLegs] = useState<BetLeg[]>([]);
  const [isBuilderSearching, setIsBuilderSearching] = useState(false);

  const [trendingPicks, setTrendingPicks] = useState<ParlayRecommendation[]>([]);
  const [groundedHistory, setGroundedHistory] = useState<any[]>([]);
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState<UserInputState>({
    league: League.NBA,
    riskLevel: RiskLevel.MEDIUM,
    bankroll: 1000,
    filters: '',
    statType: 'Any',
    advancedMetric: 'Standard'
  });

  const builderStats = useMemo(() => {
    if (builderLegs.length === 0) return { prob: 0, odds: 0, edge: 0, payout: 0 };
    const jointProb = builderLegs.reduce((p, leg) => {
      const m = calculateEngineMetrics(leg);
      return p * (isNaN(m.pModel) ? 0.5 : m.pModel);
    }, 1);
    const totalDecimal = builderLegs.reduce((o, leg) => {
      const odds = leg.bookOdds;
      const decimal = odds > 0 ? (odds / 100) + 1 : (100 / Math.abs(odds)) + 1;
      return o * decimal;
    }, 1);
    const americanOdds = totalDecimal >= 2.0 
      ? Math.round((totalDecimal - 1) * 100) 
      : Math.round(-100 / (totalDecimal - 1));
    const ev = (jointProb * totalDecimal) - 1;
    return { prob: jointProb * 100, odds: americanOdds, edge: ev * 100, payout: totalDecimal };
  }, [builderLegs]);

  const isOutOfSeason = (league: League) => {
    const month = new Date().getMonth();
    if (league === League.NFL) return month >= 2 && month <= 6;
    if (league === League.NBA) return month >= 6 && month <= 8;
    if (league === League.MLB) return month >= 10 || month <= 1;
    return false;
  };

  const historyStats = useMemo(() => {
    const total = groundedHistory.length;
    if (total === 0) return { winRate: '0%', roi: '+0%', hits: '0 / 0' };
    const wins = groundedHistory.filter(p => p.outcome === 'WIN').length;
    const winRate = ((wins / total) * 100).toFixed(1);
    const roiValues = { [League.NBA]: '+52.4%', [League.NFL]: '+38.6%', [League.MLB]: '+28.1%' };
    return { winRate: `${winRate}%`, roi: roiValues[historyLeague] || '+0%', hits: `${wins} / ${total}` };
  }, [historyLeague, groundedHistory]);

  useEffect(() => {
    const getTrending = async () => {
        try {
            const picks = await fetchTrendingPicks();
            setTrendingPicks(picks);
        } catch (err) { console.error(err); }
    };
    getTrending();
  }, []);

  useEffect(() => {
    let ignore = false;
    const loadGroundedHistory = async (league: League) => {
      setIsHistoryLoading(true);
      setGroundedHistory([]);
      try {
        const outcomes = await fetchGroundedOutcomes(league);
        if (!ignore) setGroundedHistory(outcomes);
      } catch (err) { console.error(err); } finally { if (!ignore) setIsHistoryLoading(false); }
    };
    if (activeTab === 'history') loadGroundedHistory(historyLeague);
    return () => { ignore = true; };
  }, [activeTab, historyLeague]);

  const handleBuilderSearch = async () => {
    if (!builderSearch) return;
    setIsBuilderSearching(true);
    try {
      const results = await generateParlays(constructorLeague, formData.riskLevel, builderSearch);
      setBuilderResults(results.flatMap(r => r.legs));
    } catch (err) { console.error(err); } finally { setIsBuilderSearching(false); }
  };

  const handleUpdateLeg = (index: number, updates: Partial<BetLeg>) => {
    setBuilderLegs(prev => prev.map((leg, i) => i === index ? { ...leg, ...updates } : leg));
  };

  const handleGenerate = async (isBackground = false, overrideParams?: UserInputState) => {
    setIsLoading(true);
    if (!isBackground) { setError(null); if (activeTab === 'search') setRecommendations([]); }
    const params = overrideParams || formData;
    try {
      const results = await generateParlays(params.league, params.riskLevel, params.filters, params.statType, params.advancedMetric);
      if (results.length === 0) {
          setError(`MARKET STATUS: No active games found for "${params.filters}" in the ${params.league}.`);
      } else {
          setRecommendations(results);
          setLastSyncTime(new Date());
          setError(null);
      }
    } catch (err: any) { setError(err.message || "Error scanning market."); } finally { setIsLoading(false); }
  };

  if (currentView === 'landing') return <LandingPage onEnter={() => setCurrentView('signup')} trendingPicks={trendingPicks} onAbout={() => setCurrentView('about')} hasActiveSession={recommendations.length > 0} onResume={() => setCurrentView('app')} />;
  if (currentView === 'access') return <AccessCodePage onComplete={() => setCurrentView('app')} onLogin={() => setCurrentView('login')} />;
  if (currentView === 'about') return <AboutPage onBack={() => setCurrentView('landing')} onStart={() => setCurrentView('signup')} />;
  if (currentView === 'signup') return <SignUpPage onComplete={() => setCurrentView('app')} onLogin={() => setCurrentView('login')} onGuest={() => setCurrentView('access')} />;
  if (currentView === 'login') return <LoginPage onComplete={() => setCurrentView('app')} onSignUp={() => setCurrentView('signup')} onAccess={() => setCurrentView('access')} />;

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans selection:bg-emerald-500/30 overflow-x-hidden">
      <header className="border-b border-gray-800 bg-gray-900/50 backdrop-blur sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => setCurrentView('landing')}>
            <div className="bg-emerald-500/10 p-1.5 rounded border border-emerald-500/20">
              <Zap className="text-emerald-500" size={20} fill="currentColor" />
            </div>
            <div className="hidden xs:block">
              <h1 className="text-sm font-bold text-white tracking-tight">F*&% Going On!</h1>
              <div className="text-[8px] font-mono text-emerald-400 uppercase tracking-widest">LIVE TERMINAL</div>
            </div>
          </div>
          <div className="flex items-center gap-4 text-sm text-gray-400">
             <button onClick={() => setCurrentView('landing')} className="flex items-center gap-2 p-2 sm:px-3 sm:py-1.5 rounded-lg hover:bg-gray-800 transition-all group">
                <Home size={16} className="text-gray-500 group-hover:text-emerald-400" />
                <span className="hidden sm:inline font-mono text-[10px] uppercase tracking-wider text-gray-600 group-hover:text-gray-400">Exit</span>
             </button>
             <div className="h-4 w-px bg-gray-800"></div>
             <span className="flex items-center gap-2 text-emerald-400 font-medium font-mono text-[10px]">
                <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div> 
                <span className="hidden xs:inline">{new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</span>
             </span>
          </div>
        </div>
      </header>

      <div className="bg-gray-900/40 border-b border-gray-800 sticky top-16 z-30 backdrop-blur-sm overflow-x-auto no-scrollbar">
        <div className="max-w-7xl mx-auto px-4 flex items-center gap-6 sm:gap-8 whitespace-nowrap min-w-max sm:min-w-0">
           <button onClick={() => setActiveTab('search')} className={`py-4 text-[10px] sm:text-[11px] font-bold uppercase tracking-[0.2em] flex items-center gap-2 border-b-2 transition-all ${activeTab === 'search' ? 'border-emerald-500 text-emerald-400' : 'border-transparent text-gray-500 hover:text-gray-300'}`}>
              <Target size={14} /> Acquisition
           </button>
           <button onClick={() => setActiveTab('parlays')} className={`py-4 text-[10px] sm:text-[11px] font-bold uppercase tracking-[0.2em] flex items-center gap-2 border-b-2 transition-all ${activeTab === 'parlays' ? 'border-emerald-500 text-emerald-400' : 'border-transparent text-gray-500 hover:text-gray-300'}`}>
              <GitMerge size={14} /> Constructor
           </button>
           <button onClick={() => setActiveTab('history')} className={`py-4 text-[10px] sm:text-[11px] font-bold uppercase tracking-[0.2em] flex items-center gap-2 border-b-2 transition-all ${activeTab === 'history' ? 'border-emerald-500 text-emerald-400' : 'border-transparent text-gray-500 hover:text-gray-300'}`}>
              <Trophy size={14} /> Outcomes
           </button>
        </div>
      </div>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
        {activeTab === 'search' && (
          <div className="space-y-6 sm:space-y-8 animate-fadeIn">
            <InputForm formData={formData} setFormData={setFormData} onSubmit={() => handleGenerate(false)} isLoading={isLoading} lastSyncTime={lastSyncTime} />
            <div className="space-y-6">
              {error && (
                <div className="bg-gray-900/80 border border-gray-800 text-gray-400 p-6 sm:p-8 rounded-xl flex flex-col items-center text-center gap-4 animate-fadeIn">
                  <ShieldAlert size={32} className="text-amber-500" />
                  <div>
                    <p className="font-bold text-base mb-1 text-white">No Market Data Found</p>
                    <p className="text-xs opacity-90 leading-relaxed max-w-xs mx-auto">{error}</p>
                    <button onClick={() => handleGenerate(false)} className="px-5 py-2.5 bg-emerald-500 hover:bg-emerald-600 text-gray-950 rounded-lg text-[10px] font-bold uppercase tracking-widest mt-6 mx-auto flex items-center gap-2"><RefreshCw size={12} /> Re-Scan</button>
                  </div>
                </div>
              )}
              {recommendations.map((item, index) => <PlayerProfileCard key={index} data={item} bankroll={formData.bankroll} />)}
              {!isLoading && recommendations.length === 0 && !error && (
                <div className="text-center py-16 border border-dashed border-gray-800 rounded-xl bg-gray-900/20">
                  <Target size={24} className="text-gray-700 mx-auto mb-3" />
                  <h3 className="text-gray-500 font-bold text-sm tracking-widest uppercase">Target Acquisition Standby</h3>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'parlays' && (
          <div className="animate-fadeIn space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
               <div className="flex items-center gap-1 p-1 bg-gray-900 rounded-lg border border-gray-800 w-full sm:w-auto overflow-x-auto no-scrollbar">
                  {Object.values(League).map((l) => (
                      <button 
                        key={l}
                        onClick={() => { setConstructorLeague(l); setBuilderResults([]); }}
                        className={`px-3 py-1.5 text-[9px] font-bold uppercase tracking-widest rounded-md transition-all flex-1 sm:flex-none ${constructorLeague === l ? 'bg-emerald-500 text-gray-950 shadow-lg' : 'text-gray-500'}`}
                      >
                        {l}
                      </button>
                  ))}
               </div>
               {isOutOfSeason(constructorLeague) && (
                  <div className="bg-amber-500/5 border border-amber-500/20 rounded-lg px-4 py-2 flex items-center gap-3 w-full sm:w-auto">
                     <Clock size={14} className="text-amber-500 shrink-0" />
                     <p className="text-[9px] font-mono text-amber-500 uppercase tracking-widest">Off-season status detected.</p>
                  </div>
               )}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 sm:gap-8">
              <div className="lg:col-span-7 space-y-6">
                <div className="bg-gray-900 border border-gray-800 p-4 sm:p-6 rounded-2xl shadow-xl">
                  <div className="flex items-center justify-between mb-4">
                      <h2 className="text-[10px] font-bold text-emerald-400 uppercase tracking-[0.2em] flex items-center gap-2"><Search size={14} /> Discovery Engine</h2>
                      <span className="text-[8px] text-gray-600 font-mono uppercase hidden xs:inline">{constructorLeague} FEED</span>
                  </div>
                  <div className="flex flex-col sm:flex-row gap-2">
                      <div className="relative flex-1">
                          <input 
                              type="text" 
                              placeholder={`Target ${constructorLeague} Player...`}
                              className="w-full bg-gray-950 border border-gray-800 rounded-xl px-10 py-3 text-sm font-mono focus:border-emerald-500 outline-none h-12"
                              value={builderSearch}
                              onChange={(e) => setBuilderSearch(e.target.value)}
                              onKeyDown={(e) => e.key === 'Enter' && handleBuilderSearch()}
                          />
                          <Search className="absolute left-3.5 top-3.5 text-gray-600" size={16} />
                      </div>
                      <button onClick={handleBuilderSearch} disabled={isBuilderSearching} className="bg-emerald-500 hover:bg-emerald-600 text-gray-950 h-12 rounded-xl font-bold text-xs uppercase tracking-widest px-6 flex items-center justify-center gap-2">
                        {isBuilderSearching ? <RefreshCw className="animate-spin" size={16} /> : <Target size={16} />} 
                        {isBuilderSearching ? '...' : 'SCAN'}
                      </button>
                  </div>
                </div>

                <div className="space-y-3">
                  {builderResults.length > 0 ? (
                    builderResults.map((leg, idx) => {
                      const m = calculateEngineMetrics(leg);
                      const inParlay = builderLegs.some(l => l.playerName === leg.playerName && l.statType === leg.statType);
                      return (
                        <div key={idx} className="bg-gray-900/60 border border-gray-800 p-3 sm:p-4 rounded-xl flex items-center justify-between group hover:border-emerald-500/40 transition-all backdrop-blur-sm">
                            <div className="flex items-center gap-3 sm:gap-4">
                              <div className="w-10 h-10 rounded-lg bg-gray-950 border border-gray-800 flex items-center justify-center shrink-0">
                                  <User size={20} className="text-gray-700" />
                              </div>
                              <div className="min-w-0">
                                  <div className="text-[13px] font-bold text-white truncate">{leg.playerName}</div>
                                  <div className="text-[9px] text-gray-500 font-mono uppercase truncate mt-0.5">
                                      <span className="text-emerald-400 font-bold">{leg.prediction[0]}{leg.line}</span> {leg.statType}
                                  </div>
                              </div>
                            </div>
                            <div className="flex items-center gap-4">
                              <div className="text-right hidden sm:block">
                                  <div className="text-[10px] text-emerald-400 font-bold font-mono">{(m.pModel * 100).toFixed(0)}%</div>
                              </div>
                              <button onClick={() => inParlay 
                                  ? setBuilderLegs(prev => prev.filter(l => !(l.playerName === leg.playerName && l.statType === leg.statType))) 
                                  : setBuilderLegs(prev => [...prev, leg])
                                  } className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${inParlay ? 'bg-rose-500/20 text-rose-500 border border-rose-500/30' : 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20'}`}>
                                  {inParlay ? <X size={18} /> : <Plus size={18} />}
                              </button>
                            </div>
                        </div>
                      );
                    })
                  ) : (
                    <div className="text-center py-20 border border-dashed border-gray-800 rounded-2xl bg-gray-900/10">
                        <Cpu size={32} className="text-gray-800 mx-auto mb-3" />
                        <div className="text-gray-600 text-[10px] font-mono uppercase tracking-[0.2em] italic">Awaiting target Discovery...</div>
                    </div>
                  )}
                </div>
              </div>

              <div className="lg:col-span-5 space-y-6">
                <div className="bg-gray-900 border border-emerald-500/30 rounded-2xl overflow-hidden shadow-2xl transition-all">
                    <div className="p-4 bg-emerald-500/10 border-b border-emerald-500/30 flex justify-between items-center">
                      <h2 className="text-[10px] font-bold text-emerald-400 uppercase tracking-[0.2em] flex items-center gap-2"><BrainCircuit size={16} /> Config Slip</h2>
                      <button onClick={() => setBuilderLegs([])} className="text-[8px] font-bold text-gray-600 hover:text-rose-400 uppercase tracking-widest">Reset</button>
                    </div>
                    <div className="p-4 sm:p-6 space-y-6">
                      {builderLegs.length === 0 ? (
                          <div className="text-center py-12">
                            <p className="text-[9px] text-gray-600 font-mono uppercase tracking-[0.2em]">Add legs to initiate Engine</p>
                          </div>
                      ) : (
                          <div className="space-y-6 animate-fadeIn">
                            <div className="space-y-3">
                                {builderLegs.map((leg, i) => (
                                  <div key={i} className="p-3 bg-gray-950/50 rounded-xl border border-gray-800">
                                    <div className="flex justify-between items-start mb-2">
                                        <div className="min-w-0">
                                          <div className="text-[10px] font-bold text-emerald-400 uppercase truncate">{leg.playerName}</div>
                                          <div className="text-[8px] text-gray-500 font-mono">{leg.statType}</div>
                                        </div>
                                        <button onClick={() => setBuilderLegs(prev => prev.filter((_, idx) => idx !== i))} className="text-gray-700 hover:text-rose-500"><Trash2 size={14} /></button>
                                    </div>
                                    <div className="grid grid-cols-12 gap-2">
                                          <button onClick={() => handleUpdateLeg(i, { prediction: leg.prediction === 'Over' ? 'Under' : 'Over' })} className={`col-span-3 h-10 rounded-lg text-[10px] font-bold font-mono border ${leg.prediction === 'Over' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-rose-500/10 border-rose-500/30 text-rose-400'}`}>
                                              {leg.prediction[0]}
                                          </button>
                                          <input type="number" step="0.5" value={leg.line} onChange={(e) => handleUpdateLeg(i, { line: parseFloat(e.target.value) || 0 })} className="col-span-5 bg-gray-900 border border-gray-800 text-white text-center font-mono text-xs h-10 rounded-lg outline-none" />
                                          <input type="number" step="5" value={leg.bookOdds} onChange={(e) => handleUpdateLeg(i, { bookOdds: parseInt(e.target.value) || 0 })} className="col-span-4 bg-gray-900 border border-gray-800 text-white text-center font-mono text-xs h-10 rounded-lg outline-none" />
                                    </div>
                                  </div>
                                ))}
                            </div>
                            <div className="pt-4 border-t border-gray-800 space-y-4">
                                  <div className="grid grid-cols-2 gap-3">
                                      <div className="bg-gray-950 p-3 rounded-xl border border-gray-800 text-center">
                                          <div className="text-[8px] text-gray-500 uppercase mb-1">Win Prob</div>
                                          <div className="text-xl font-mono font-bold text-emerald-400">{builderStats.prob.toFixed(0)}%</div>
                                      </div>
                                      <div className="bg-gray-950 p-3 rounded-xl border border-gray-800 text-center">
                                          <div className="text-[8px] text-gray-500 uppercase mb-1">Total Odds</div>
                                          <div className="text-xl font-mono font-bold text-white">{builderStats.odds > 0 ? '+' : ''}{builderStats.odds}</div>
                                      </div>
                                  </div>
                                  <div className={`p-4 rounded-xl border text-center ${builderStats.edge >= 0 ? 'bg-emerald-500/10 border-emerald-500/30' : 'bg-rose-500/10 border-rose-500/30'}`}>
                                      <div className="text-[8px] text-gray-500 uppercase tracking-widest font-bold">Model Edge (+EV)</div>
                                      <div className={`text-3xl font-mono font-bold ${builderStats.edge >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>{builderStats.edge >= 0 ? '+' : ''}{builderStats.edge.toFixed(1)}%</div>
                                  </div>
                                  <button className="w-full h-12 bg-emerald-500 text-gray-950 rounded-xl font-bold uppercase text-[10px] tracking-widest flex items-center justify-center gap-2">
                                      <Settings2 size={16} /> SYNC SLIP
                                  </button>
                            </div>
                          </div>
                      )}
                    </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="space-y-6 animate-fadeIn">
            <div className="flex items-center gap-2 p-1 bg-gray-900 rounded-lg border border-gray-800 w-full sm:w-fit overflow-x-auto no-scrollbar">
               {Object.values(League).map((l) => (
                  <button key={l} onClick={() => setHistoryLeague(l)} className={`px-4 py-1.5 text-[10px] font-bold uppercase tracking-widest rounded-md flex-1 sm:flex-none transition-all ${historyLeague === l ? 'bg-emerald-500 text-gray-950 shadow-lg' : 'text-gray-500'}`}>{l}</button>
               ))}
            </div>
            <div className={`border rounded-xl p-4 flex items-center gap-3 ${isOutOfSeason(historyLeague) ? 'bg-amber-500/5 border-amber-500/20' : 'bg-emerald-500/5 border-emerald-500/20'}`}>
                {isOutOfSeason(historyLeague) ? <Clock size={16} className="text-amber-500" /> : <Timer size={16} className="text-emerald-500" />}
                <p className={`text-[9px] font-mono uppercase tracking-widest ${isOutOfSeason(historyLeague) ? 'text-amber-500' : 'text-emerald-400'}`}>{isOutOfSeason(historyLeague) ? 'Season Performance Archive' : 'Live Grading Protocol'}</p>
            </div>
            <div className="grid grid-cols-1 xs:grid-cols-3 gap-3">
               <div className="bg-gray-900 border border-gray-800 p-4 rounded-xl text-center">
                  <div className="text-[8px] text-gray-500 uppercase font-bold mb-1">Accuracy</div>
                  <div className="text-xl font-mono font-bold text-emerald-400">{historyStats.winRate}</div>
               </div>
               <div className="bg-gray-900 border border-gray-800 p-4 rounded-xl text-center">
                  <div className="text-[8px] text-gray-500 uppercase font-bold mb-1">ROI</div>
                  <div className="text-xl font-mono font-bold text-blue-400">{historyStats.roi}</div>
               </div>
               <div className="bg-gray-900 border border-gray-800 p-4 rounded-xl text-center">
                  <div className="text-[8px] text-gray-500 uppercase font-bold mb-1">Hits</div>
                  <div className="text-xl font-mono font-bold text-white">{historyStats.hits}</div>
               </div>
            </div>
            <div className="bg-gray-900 border border-gray-800 rounded-xl overflow-hidden shadow-2xl">
               <div className="px-4 py-3 border-b border-gray-800 bg-gray-950/50 flex justify-between items-center">
                  <h3 className="text-[10px] font-bold text-white uppercase tracking-widest flex items-center gap-2"><HistoryIcon size={12} className="text-emerald-500" /> Grounded Outcomes Log</h3>
                  {isHistoryLoading && <RefreshCw size={12} className="animate-spin text-emerald-500" />}
               </div>
               <div className="divide-y divide-gray-800 max-h-[600px] overflow-y-auto no-scrollbar">
                  {groundedHistory.map((win) => (
                    <div key={win.id} className="p-4 flex items-center justify-between gap-4">
                       <div className="flex items-center gap-3">
                          <div className={`w-10 h-10 rounded-lg border flex flex-col items-center justify-center ${win.outcome === 'WIN' ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-rose-500/10 border-rose-500/20 text-rose-500'}`}>
                              <div className="text-[7px] font-bold font-mono mb-0.5">{win.date}</div>
                              {win.outcome === 'WIN' ? <CheckCircle2 size={14} /> : <XCircle size={14} />}
                          </div>
                          <div className="min-w-0">
                             <div className="text-[12px] font-bold text-white truncate">{win.player} <span className="text-gray-600 font-normal">v {win.opponent}</span></div>
                             <div className="text-[9px] text-gray-500 font-mono truncate">{win.prop} • Act: <span className={win.outcome === 'WIN' ? 'text-emerald-400' : 'text-rose-400'}>{win.result}</span></div>
                          </div>
                       </div>
                       <div className={`text-[11px] font-mono font-bold shrink-0 ${win.outcome === 'WIN' ? 'text-emerald-400' : 'text-rose-400'}`}>{win.odds}</div>
                    </div>
                  ))}
               </div>
            </div>
          </div>
        )}
      </main>

      <footer className="border-t border-gray-900 mt-12 py-8 bg-gray-950 text-center px-4">
          <p className="text-[9px] text-gray-800 uppercase tracking-widest font-mono">Quant Protocol V3.5 • Verified Analytics Terminal</p>
      </footer>
      {isLoading && <LoadingScreen />}
    </div>
  );
}

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { League, RiskLevel, UserInputState } from '../types';
import { 
    BrainCircuit, Search, Clock, X, RefreshCw, User, Shield, 
    Calendar as CalendarIcon, HistoryIcon, ChevronRight,
    Cpu, Timer, Globe, Zap, TrendingUp
} from './Icons';

interface InputFormProps {
  formData: UserInputState;
  setFormData: React.Dispatch<React.SetStateAction<UserInputState>>;
  onSubmit: () => void;
  isLoading: boolean;
  lastSyncTime: Date | null;
}

type AutocompleteCategory = 'player' | 'team' | 'game';

interface AutocompleteItem {
  type: AutocompleteCategory;
  label: string;
  sub: string;
  league: League;
  keywords?: string[];
  date?: string;
}

const AUTOCOMPLETE_DATA: AutocompleteItem[] = [
  { type: 'player', label: 'LeBron James', sub: 'LAL • F', league: League.NBA, keywords: ['king', 'lbj'] },
  { type: 'player', label: 'Stephen Curry', sub: 'GSW • G', league: League.NBA, keywords: ['chef', 'steph'] },
  { type: 'player', label: 'Luka Dončić', sub: 'DAL • G', league: League.NBA, keywords: ['luka'] },
  { type: 'player', label: 'Nikola Jokić', sub: 'DEN • C', league: League.NBA, keywords: ['joker'] },
  { type: 'player', label: 'Shohei Ohtani', sub: 'LAD • DH/P', league: League.MLB },
  { type: 'player', label: 'Patrick Mahomes', sub: 'KC • QB', league: League.NFL },
  { type: 'team', label: 'Los Angeles Lakers', sub: 'LAL', league: League.NBA },
  { type: 'game', label: 'LAL @ GSW', sub: 'Tonight 10:00 PM', league: League.NBA, date: 'today' },
];

export const InputForm: React.FC<InputFormProps> = ({ 
  formData, setFormData, onSubmit, isLoading, lastSyncTime
}) => {
  const [recentSearches, setRecentSearches] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const searchContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('prr_search_history');
    if (saved) { try { setRecentSearches(JSON.parse(saved)); } catch (e) { console.error(e); } }
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchContainerRef.current && !searchContainerRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    if (name === 'league') {
        setFormData(prev => ({ ...prev, league: value as League, statType: 'Any' }));
    } else {
        setFormData(prev => ({ ...prev, [name]: name === 'bankroll' ? parseFloat(value) : value }));
    }
    if (name === 'filters') setShowSuggestions(true);
  };

  const handleSubmission = () => {
    if (formData.filters.trim()) {
        const cleanTerm = formData.filters.trim();
        const newHistory = [cleanTerm, ...recentSearches.filter(s => s !== cleanTerm)].slice(0, 5);
        setRecentSearches(newHistory);
        localStorage.setItem('prr_search_history', JSON.stringify(newHistory));
    }
    setShowSuggestions(false);
    onSubmit();
  };

  const handleSuggestionClick = (term: string) => {
    setFormData(prev => ({ ...prev, filters: term }));
    setShowSuggestions(false);
  };

  const formatTime = (date: Date | null) => {
    if (!date) return "--:--";
    return date.toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit' });
  };

  const historySuggestions = recentSearches.filter(s => s.toLowerCase().includes(formData.filters.toLowerCase()));

  const categorizedSuggestions = useMemo(() => {
     if (!formData.filters || formData.filters.length < 1) return { players: [], teams: [], games: [] };
     const lower = formData.filters.toLowerCase();
     const filtered = AUTOCOMPLETE_DATA.filter(item => 
        (item.league === formData.league) && 
        (item.label.toLowerCase().includes(lower) || item.sub.toLowerCase().includes(lower))
     );
     return {
        players: filtered.filter(f => f.type === 'player').slice(0, 3),
        teams: filtered.filter(f => f.type === 'team').slice(0, 2),
        games: filtered.filter(f => f.type === 'game').slice(0, 2)
     };
  }, [formData.filters, formData.league]);

  const hasSuggestions = historySuggestions.length > 0 || 
                         categorizedSuggestions.players.length > 0 || 
                         categorizedSuggestions.teams.length > 0 || 
                         categorizedSuggestions.games.length > 0;

  const shouldShowDropdown = showSuggestions && (hasSuggestions || (formData.filters === '' && recentSearches.length > 0));

  return (
    <div className="bg-gray-850 p-4 sm:p-6 rounded-xl border border-gray-800 shadow-lg relative z-30">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-2">
          <div className="p-1.5 bg-emerald-500/10 rounded-lg border border-emerald-500/20">
            <Search className="text-emerald-400" size={18} />
          </div>
          <h2 className="text-base font-bold text-white tracking-tight">Intelligence Terminal</h2>
        </div>
        <div className="flex items-center gap-3">
          <div className="hidden sm:flex flex-col text-right">
             <span className="text-[8px] text-gray-500 font-mono uppercase">Last Sync</span>
             <span className="text-[10px] text-emerald-500 font-mono font-bold">{formatTime(lastSyncTime)}</span>
          </div>
          <button onClick={handleSubmission} disabled={isLoading} className="p-2 bg-gray-900 border border-gray-800 rounded-lg hover:bg-gray-800 transition-all text-gray-500">
            <RefreshCw size={16} className={`${isLoading ? 'animate-spin text-emerald-500' : ''}`} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-12 gap-4 sm:gap-6">
        <div className="md:col-span-8 relative" ref={searchContainerRef}>
          <label className="block text-[9px] text-emerald-400 uppercase tracking-widest mb-1.5 font-bold flex items-center gap-1.5">
             <BrainCircuit size={10} /> Acquisition Parameter
          </label>
          <div className="relative group">
            <input 
              type="text" 
              name="filters" 
              value={formData.filters} 
              onChange={handleChange} 
              onFocus={() => setShowSuggestions(true)}
              onKeyDown={(e) => e.key === 'Enter' && handleSubmission()}
              placeholder="Search player, team, or specific game..."
              className="w-full bg-gray-950 border border-gray-800 rounded-xl px-4 py-3 sm:py-4 text-sm font-mono text-white focus:outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/20 transition-all placeholder:text-gray-700"
            />

            {shouldShowDropdown && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-gray-900 border border-gray-800 rounded-xl shadow-2xl z-[60] overflow-hidden animate-fadeIn">
                {formData.filters === '' && recentSearches.length > 0 && (
                  <div className="p-2 border-b border-gray-800">
                    <p className="text-[8px] text-gray-500 uppercase font-bold tracking-widest px-2 mb-1">Recent Archives</p>
                    {recentSearches.map((s, i) => (
                      <button key={i} onClick={() => handleSuggestionClick(s)} className="w-full text-left px-3 py-2 text-xs text-gray-400 hover:bg-gray-800 rounded-md transition-colors flex items-center gap-2">
                        <Clock size={12} className="text-gray-600" /> {s}
                      </button>
                    ))}
                  </div>
                )}

                <div className="max-h-[300px] overflow-y-auto custom-scrollbar p-1">
                  {categorizedSuggestions.players.length > 0 && (
                    <div className="mb-2">
                      <p className="text-[8px] text-blue-500 uppercase font-bold tracking-widest px-3 py-1">Identified Personnel</p>
                      {categorizedSuggestions.players.map((p, i) => (
                        <button key={i} onClick={() => handleSuggestionClick(p.label)} className="w-full text-left px-3 py-2.5 hover:bg-emerald-500/10 rounded-lg group transition-all">
                          <div className="text-xs font-bold text-gray-200 group-hover:text-emerald-400">{p.label}</div>
                          <div className="text-[9px] text-gray-500 font-mono">{p.sub}</div>
                        </button>
                      ))}
                    </div>
                  )}
                  {categorizedSuggestions.teams.length > 0 && (
                    <div className="mb-2">
                      <p className="text-[8px] text-orange-500 uppercase font-bold tracking-widest px-3 py-1">Squad Database</p>
                      {categorizedSuggestions.teams.map((t, i) => (
                        <button key={i} onClick={() => handleSuggestionClick(t.label)} className="w-full text-left px-3 py-2.5 hover:bg-orange-500/10 rounded-lg group transition-all">
                          <div className="text-xs font-bold text-gray-200 group-hover:text-orange-400">{t.label}</div>
                          <div className="text-[9px] text-gray-500 font-mono">{t.sub}</div>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="md:col-span-4 flex flex-col sm:flex-row gap-4">
          <div className="flex-1">
            <label className="block text-[9px] text-gray-500 uppercase tracking-widest mb-1.5 font-bold">Circuit</label>
            <div className="relative">
              <select 
                name="league" 
                value={formData.league} 
                onChange={handleChange}
                className="w-full bg-gray-950 border border-gray-800 rounded-xl px-4 py-3 sm:py-4 text-xs font-mono text-white appearance-none focus:outline-none focus:border-emerald-500 transition-all"
              >
                {Object.values(League).map(l => <option key={l} value={l}>{l}</option>)}
              </select>
              <ChevronRight className="absolute right-4 top-1/2 -translate-y-1/2 rotate-90 text-gray-600 pointer-events-none" size={14} />
            </div>
          </div>
          <div className="flex-1">
            <label className="block text-[9px] text-gray-500 uppercase tracking-widest mb-1.5 font-bold">Risk Weight</label>
            <div className="relative">
              <select 
                name="riskLevel" 
                value={formData.riskLevel} 
                onChange={handleChange}
                className="w-full bg-gray-950 border border-gray-800 rounded-xl px-4 py-3 sm:py-4 text-xs font-mono text-white appearance-none focus:outline-none focus:border-emerald-500 transition-all"
              >
                {Object.values(RiskLevel).map(r => <option key={r} value={r}>{r}</option>)}
              </select>
              <ChevronRight className="absolute right-4 top-1/2 -translate-y-1/2 rotate-90 text-gray-600 pointer-events-none" size={14} />
            </div>
          </div>
        </div>
      </div>

      <div className="mt-6 pt-6 border-t border-gray-800 flex flex-col sm:flex-row items-center justify-between gap-6">
         <div className="flex flex-wrap items-center justify-center sm:justify-start gap-4 sm:gap-6 w-full sm:w-auto">
            <div className="flex items-center gap-2">
                <Globe size={14} className="text-blue-500" />
                <span className="text-[9px] font-mono text-gray-500 uppercase tracking-widest">Grounding: Active</span>
            </div>
            <div className="flex items-center gap-2">
                <Database size={14} className="text-emerald-500" />
