    const regex = /(MATH:|Line|μ|σ|ROI|Z-Score|Edge|discrepancy|[-+]?\d*\.?\d+%?|OVER|UNDER)/gi;
    const parts = text.split(regex);

    return (
        <span className="font-sans">
